-- ============================================================
-- 0001_phase1_foundation.sql
-- ============================================================
-- ============================================================
-- KHATAFY | PHASE 1 DATABASE FOUNDATION
-- Supabase PostgreSQL
-- Includes: profiles, groups, memberships, invitations,
-- join requests, audit logs, RLS, triggers and secure RPCs.
--
-- Run once in Supabase SQL Editor using the project owner role.
-- Review the notes in the accompanying setup instructions.
-- ============================================================

begin;

-- 1. Extensions
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- 2. Core tables
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default '',
  phone text,
  avatar_url text,
  preferred_language text not null default 'en'
    check (preferred_language in ('en', 'hi')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.groups (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(trim(name)) between 2 and 80),
  description text check (description is null or char_length(description) <= 500),
  created_by uuid not null references public.profiles(id),
  currency_code text not null default 'INR'
    check (currency_code ~ '^[A-Z]{3}$'),
  timezone text not null default 'Asia/Kolkata',
  status text not null default 'active'
    check (status in ('active', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.group_members (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete restrict,
  role text not null default 'member'
    check (role in ('owner', 'admin', 'member')),
  status text not null default 'active'
    check (status in ('active', 'left', 'removed')),
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (status = 'active' and left_at is null)
    or
    (status in ('left', 'removed') and left_at is not null)
  )
);

-- A user can have only one active membership in a group.
-- Old membership rows remain available for history.
create unique index if not exists uq_group_members_active
  on public.group_members(group_id, user_id)
  where status = 'active';

-- Each group must have at most one active owner.
create unique index if not exists uq_group_one_active_owner
  on public.group_members(group_id)
  where role = 'owner' and status = 'active';

create table if not exists public.group_invitations (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  token_hash text not null unique,
  created_by uuid not null references public.profiles(id),
  expires_at timestamptz,
  max_uses integer check (max_uses is null or max_uses > 0),
  uses_count integer not null default 0 check (uses_count >= 0),
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.join_requests (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  invitation_id uuid not null references public.group_invitations(id) on delete restrict,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected', 'cancelled')),
  message text check (message is null or char_length(message) <= 300),
  reviewed_by uuid references public.profiles(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (status = 'pending' and reviewed_by is null and reviewed_at is null)
    or
    (status <> 'pending' and reviewed_by is not null and reviewed_at is not null)
  )
);

create unique index if not exists uq_join_request_pending
  on public.join_requests(group_id, user_id)
  where status = 'pending';

create table if not exists public.audit_logs (
  id bigint generated always as identity primary key,
  group_id uuid references public.groups(id) on delete set null,
  actor_id uuid references public.profiles(id) on delete set null,
  action text not null,
  entity_type text not null,
  entity_id text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- 3. Indexes
create index if not exists idx_group_members_user_status
  on public.group_members(user_id, status);

create index if not exists idx_group_members_group_status
  on public.group_members(group_id, status);

create index if not exists idx_groups_created_by
  on public.groups(created_by);

create index if not exists idx_group_invitations_group
  on public.group_invitations(group_id);

create index if not exists idx_join_requests_user_status
  on public.join_requests(user_id, status, created_at desc);

create index if not exists idx_join_requests_group_status
  on public.join_requests(group_id, status, created_at desc);

create index if not exists idx_audit_logs_group_created
  on public.audit_logs(group_id, created_at desc);

create index if not exists idx_audit_logs_actor_created
  on public.audit_logs(actor_id, created_at desc);

-- 4. Updated-at trigger helper
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_profiles_updated_at on public.profiles;
create trigger trg_profiles_updated_at
before update on public.profiles
for each row execute function public.set_updated_at();

drop trigger if exists trg_groups_updated_at on public.groups;
create trigger trg_groups_updated_at
before update on public.groups
for each row execute function public.set_updated_at();

drop trigger if exists trg_group_members_updated_at on public.group_members;
create trigger trg_group_members_updated_at
before update on public.group_members
for each row execute function public.set_updated_at();

drop trigger if exists trg_join_requests_updated_at on public.join_requests;
create trigger trg_join_requests_updated_at
before update on public.join_requests
for each row execute function public.set_updated_at();

-- 5. Automatically create a profile after Supabase Auth signup
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text;
begin
  v_name := coalesce(
    nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'name'), ''),
    split_part(coalesce(new.email, ''), '@', 1),
    'Khatafy User'
  );

  insert into public.profiles (id, full_name)
  values (new.id, v_name)
  on conflict (id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created_khatafy on auth.users;
create trigger on_auth_user_created_khatafy
after insert on auth.users
for each row execute function public.handle_new_user();

-- Backfill profiles for users who already exist in Auth.
insert into public.profiles (id, full_name)
select
  u.id,
  coalesce(
    nullif(trim(u.raw_user_meta_data ->> 'full_name'), ''),
    nullif(trim(u.raw_user_meta_data ->> 'name'), ''),
    nullif(split_part(coalesce(u.email, ''), '@', 1), ''),
    'Khatafy User'
  )
from auth.users u
on conflict (id) do nothing;

-- 6. Security helper functions
-- SECURITY DEFINER avoids recursive RLS checks on group_members.
create or replace function public.is_group_member(p_group_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.group_members gm
    where gm.group_id = p_group_id
      and gm.user_id = (select auth.uid())
      and gm.status = 'active'
  );
$$;

create or replace function public.is_group_admin(p_group_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.group_members gm
    where gm.group_id = p_group_id
      and gm.user_id = (select auth.uid())
      and gm.status = 'active'
      and gm.role in ('owner', 'admin')
  );
$$;

create or replace function public.is_group_owner(p_group_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.group_members gm
    where gm.group_id = p_group_id
      and gm.user_id = (select auth.uid())
      and gm.status = 'active'
      and gm.role = 'owner'
  );
$$;

-- 7. Audit trigger
create or replace function public.write_group_audit_log()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb;
  v_old jsonb;
  v_group_id uuid;
  v_entity_id text;
  v_action text;
  v_metadata jsonb;
begin
  if tg_op <> 'DELETE' then
    v_new := to_jsonb(new);
  end if;

  if tg_op <> 'INSERT' then
    v_old := to_jsonb(old);
  end if;

  v_group_id := coalesce(
    nullif(v_new ->> 'group_id', '')::uuid,
    nullif(v_old ->> 'group_id', '')::uuid,
    nullif(v_new ->> 'id', '')::uuid,
    nullif(v_old ->> 'id', '')::uuid
  );

  v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');
  v_action := lower(tg_op);

  -- Do not copy sensitive fields such as invitation token hashes.
  v_metadata := jsonb_build_object(
    'table', tg_table_name,
    'operation', v_action
  );

  insert into public.audit_logs (
    group_id, actor_id, action, entity_type, entity_id, metadata
  )
  values (
    v_group_id,
    (select auth.uid()),
    v_action,
    tg_table_name,
    v_entity_id,
    v_metadata
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_audit_groups on public.groups;
create trigger trg_audit_groups
after insert or update or delete on public.groups
for each row execute function public.write_group_audit_log();

drop trigger if exists trg_audit_group_members on public.group_members;
create trigger trg_audit_group_members
after insert or update or delete on public.group_members
for each row execute function public.write_group_audit_log();

drop trigger if exists trg_audit_join_requests on public.join_requests;
create trigger trg_audit_join_requests
after insert or update or delete on public.join_requests
for each row execute function public.write_group_audit_log();

-- 8. Create a group and make the creator its owner atomically
create or replace function public.create_group(
  p_name text,
  p_description text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_group_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if p_name is null or char_length(trim(p_name)) not between 2 and 80 then
    raise exception 'Group name must be between 2 and 80 characters';
  end if;

  if p_description is not null and char_length(p_description) > 500 then
    raise exception 'Description is too long';
  end if;

  insert into public.groups (name, description, created_by)
  values (trim(p_name), nullif(trim(p_description), ''), v_user_id)
  returning id into v_group_id;

  insert into public.group_members (group_id, user_id, role, status)
  values (v_group_id, v_user_id, 'owner', 'active');

  return v_group_id;
end;
$$;

-- 9. Create invitation. Raw code is returned once; only its hash is stored.
create or replace function public.create_group_invitation(
  p_group_id uuid,
  p_expires_at timestamptz default (now() + interval '7 days'),
  p_max_uses integer default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_code text;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if not public.is_group_admin(p_group_id) then
    raise exception 'Only group admins can create invitations' using errcode = '42501';
  end if;

  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'Invitation expiry must be in the future';
  end if;

  if p_max_uses is not null and p_max_uses < 1 then
    raise exception 'Maximum uses must be positive';
  end if;

  v_code := encode(extensions.gen_random_bytes(24), 'hex');

  insert into public.group_invitations (
    group_id, token_hash, created_by, expires_at, max_uses
  )
  values (
    p_group_id,
    encode(extensions.digest(convert_to(v_code, 'UTF8'), 'sha256'), 'hex'),
    (select auth.uid()),
    p_expires_at,
    p_max_uses
  );

  return v_code;
end;
$$;

-- 10. Revoke an invitation without exposing invitation hashes
create or replace function public.revoke_group_invitation(p_invitation_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_group_id uuid;
begin
  select gi.group_id into v_group_id
  from public.group_invitations gi
  where gi.id = p_invitation_id;

  if v_group_id is null then
    raise exception 'Invitation not found';
  end if;

  if not public.is_group_admin(v_group_id) then
    raise exception 'Only group admins can revoke invitations' using errcode = '42501';
  end if;

  update public.group_invitations
  set revoked_at = coalesce(revoked_at, now())
  where id = p_invitation_id;
end;
$$;

-- 11. Request to join. A valid code creates a pending request only.
create or replace function public.request_to_join_group(
  p_invitation_code text,
  p_message text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_invitation public.group_invitations%rowtype;
  v_group_status text;
  v_request_id uuid;
  v_hash text;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if p_invitation_code is null or char_length(p_invitation_code) < 20 then
    raise exception 'Invalid invitation code';
  end if;

  if p_message is not null and char_length(p_message) > 300 then
    raise exception 'Message is too long';
  end if;

  v_hash := encode(
    extensions.digest(convert_to(trim(p_invitation_code), 'UTF8'), 'sha256'),
    'hex'
  );

  select * into v_invitation
  from public.group_invitations gi
  where gi.token_hash = v_hash
  for update;

  if not found
     or v_invitation.revoked_at is not null
     or (v_invitation.expires_at is not null and v_invitation.expires_at <= now())
     or (v_invitation.max_uses is not null and v_invitation.uses_count >= v_invitation.max_uses)
  then
    raise exception 'Invitation is invalid, expired, revoked or fully used';
  end if;

  select g.status into v_group_status
  from public.groups g
  where g.id = v_invitation.group_id;

  if v_group_status is distinct from 'active' then
    raise exception 'This group is not accepting join requests';
  end if;

  if exists (
    select 1 from public.group_members gm
    where gm.group_id = v_invitation.group_id
      and gm.user_id = v_user_id
      and gm.status = 'active'
  ) then
    raise exception 'You are already an active member';
  end if;

  insert into public.join_requests (
    group_id, user_id, invitation_id, message
  )
  values (
    v_invitation.group_id, v_user_id, v_invitation.id, nullif(trim(p_message), '')
  )
  on conflict (group_id, user_id) where status = 'pending'
  do update set
    invitation_id = excluded.invitation_id,
    message = excluded.message,
    updated_at = now()
  returning id into v_request_id;

  return v_request_id;
end;
$$;

-- 12. Admin approves or rejects a pending join request
create or replace function public.review_join_request(
  p_request_id uuid,
  p_decision text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request public.join_requests%rowtype;
  v_invitation public.group_invitations%rowtype;
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if p_decision not in ('approved', 'rejected') then
    raise exception 'Decision must be approved or rejected';
  end if;

  select * into v_request
  from public.join_requests jr
  where jr.id = p_request_id
  for update;

  if not found then
    raise exception 'Join request not found';
  end if;

  if not public.is_group_admin(v_request.group_id) then
    raise exception 'Only group admins can review requests' using errcode = '42501';
  end if;

  if v_request.status <> 'pending' then
    raise exception 'This request has already been reviewed';
  end if;

  if p_decision = 'approved' and not exists (
    select 1 from public.groups g
    where g.id = v_request.group_id and g.status = 'active'
  ) then
    raise exception 'Archived groups cannot accept new members';
  end if;

  if p_decision = 'approved' then
    select * into v_invitation
    from public.group_invitations gi
    where gi.id = v_request.invitation_id
    for update;

    if v_invitation.revoked_at is not null then
      raise exception 'The invitation has been revoked';
    end if;

    if v_invitation.max_uses is not null
       and v_invitation.uses_count >= v_invitation.max_uses then
      raise exception 'Invitation usage limit reached';
    end if;

    insert into public.group_members (group_id, user_id, role, status)
    values (v_request.group_id, v_request.user_id, 'member', 'active')
    on conflict (group_id, user_id) where status = 'active'
    do nothing;

    update public.group_invitations
    set uses_count = uses_count + 1
    where id = v_invitation.id;
  end if;

  update public.join_requests
  set status = p_decision,
      reviewed_by = (select auth.uid()),
      reviewed_at = now(),
      updated_at = now()
  where id = p_request_id;
end;
$$;

-- 13. A member can leave voluntarily. The owner must transfer ownership first.
create or replace function public.leave_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_role text;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  select gm.role into v_role
  from public.group_members gm
  where gm.group_id = p_group_id
    and gm.user_id = v_user_id
    and gm.status = 'active'
  for update;

  if v_role is null then
    raise exception 'Active membership not found';
  end if;

  if v_role = 'owner' then
    raise exception 'Group owner must transfer ownership or archive the group first';
  end if;

  update public.group_members
  set status = 'left', left_at = now()
  where group_id = p_group_id
    and user_id = v_user_id
    and status = 'active';
end;
$$;

-- 14. Admin removes a member. Owners cannot be removed.
-- Only the owner can remove another admin.
create or replace function public.remove_group_member(
  p_group_id uuid,
  p_user_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_actor_role text;
  v_target_role text;
begin
  if v_actor_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if v_actor_id = p_user_id then
    raise exception 'Use leave_group to leave voluntarily';
  end if;

  select gm.role into v_actor_role
  from public.group_members gm
  where gm.group_id = p_group_id
    and gm.user_id = v_actor_id
    and gm.status = 'active';

  if v_actor_role not in ('owner', 'admin') or v_actor_role is null then
    raise exception 'Only group admins can remove members' using errcode = '42501';
  end if;

  select gm.role into v_target_role
  from public.group_members gm
  where gm.group_id = p_group_id
    and gm.user_id = p_user_id
    and gm.status = 'active'
  for update;

  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;

  if v_target_role = 'owner' then
    raise exception 'The group owner cannot be removed';
  end if;

  if v_target_role = 'admin' and v_actor_role <> 'owner' then
    raise exception 'Only the owner can remove another admin' using errcode = '42501';
  end if;

  update public.group_members
  set status = 'removed', left_at = now()
  where group_id = p_group_id
    and user_id = p_user_id
    and status = 'active';
end;
$$;

-- 15. Archive a group. Only its owner can do this.
create or replace function public.archive_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.is_group_owner(p_group_id) then
    raise exception 'Only the group owner can archive this group' using errcode = '42501';
  end if;

  update public.groups
  set status = 'archived'
  where id = p_group_id and status = 'active';

  update public.group_invitations
  set revoked_at = coalesce(revoked_at, now())
  where group_id = p_group_id and revoked_at is null;
end;
$$;


-- 15A. Owner manages admin/member roles. Owner role itself cannot be changed here.
create or replace function public.set_group_member_role(
  p_group_id uuid,
  p_user_id uuid,
  p_new_role text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_target_role text;
begin
  if v_actor_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  if p_new_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member';
  end if;

  if not public.is_group_owner(p_group_id) then
    raise exception 'Only the group owner can manage admin roles' using errcode = '42501';
  end if;

  select gm.role into v_target_role
  from public.group_members gm
  where gm.group_id = p_group_id
    and gm.user_id = p_user_id
    and gm.status = 'active'
  for update;

  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;

  if v_target_role = 'owner' then
    raise exception 'Owner role cannot be changed using this function';
  end if;

  update public.group_members
  set role = p_new_role
  where group_id = p_group_id
    and user_id = p_user_id
    and status = 'active';
end;
$$;

-- 16. Row Level Security
alter table public.profiles enable row level security;
alter table public.groups enable row level security;
alter table public.group_members enable row level security;
alter table public.group_invitations enable row level security;
alter table public.join_requests enable row level security;
alter table public.audit_logs enable row level security;

-- Profiles: users can see themselves and people sharing an active group.
drop policy if exists profiles_select_self_or_groupmate on public.profiles;
create policy profiles_select_self_or_groupmate
on public.profiles
for select
to authenticated
using (
  id = (select auth.uid())
  or exists (
    select 1
    from public.group_members mine
    join public.group_members theirs
      on theirs.group_id = mine.group_id
    where mine.user_id = (select auth.uid())
      and theirs.user_id = profiles.id
      and mine.status = 'active'
      and theirs.status = 'active'
  )
);

drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self
on public.profiles
for update
to authenticated
using (id = (select auth.uid()))
with check (id = (select auth.uid()));

-- Groups: active members can read; admins can update.
drop policy if exists groups_select_members on public.groups;
create policy groups_select_members
on public.groups
for select
to authenticated
using (public.is_group_member(id));

drop policy if exists groups_update_admins on public.groups;
create policy groups_update_admins
on public.groups
for update
to authenticated
using (public.is_group_admin(id))
with check (public.is_group_admin(id));

-- Memberships: members can view their own group roster.
-- No direct insert/update/delete policies.
drop policy if exists group_members_select_roster on public.group_members;
create policy group_members_select_roster
on public.group_members
for select
to authenticated
using (public.is_group_member(group_id));

-- Invitations: intentionally no client-facing policies or table grants.
-- All invitation actions happen through security-definer RPC functions.

-- Join requests: requester sees own; group admins see requests for their group.
drop policy if exists join_requests_select_requester_or_admin on public.join_requests;
create policy join_requests_select_requester_or_admin
on public.join_requests
for select
to authenticated
using (
  user_id = (select auth.uid())
  or public.is_group_admin(group_id)
);

-- Audit logs: active group members can read group audit history.
drop policy if exists audit_logs_select_group_members on public.audit_logs;
create policy audit_logs_select_group_members
on public.audit_logs
for select
to authenticated
using (
  group_id is not null
  and public.is_group_member(group_id)
);

-- 17. Privileges: explicit allow-list
revoke all on public.profiles from anon, authenticated;
revoke all on public.groups from anon, authenticated;
revoke all on public.group_members from anon, authenticated;
revoke all on public.group_invitations from anon, authenticated;
revoke all on public.join_requests from anon, authenticated;
revoke all on public.audit_logs from anon, authenticated;

grant usage on schema public to authenticated;

grant select on public.profiles to authenticated;
grant update (full_name, phone, avatar_url, preferred_language)
  on public.profiles to authenticated;

grant select on public.groups to authenticated;
grant update (name, description, timezone)
  on public.groups to authenticated;

grant select on public.group_members to authenticated;
grant select on public.join_requests to authenticated;
grant select on public.audit_logs to authenticated;

-- Helper functions must be callable by RLS policies.
revoke all on function public.is_group_member(uuid) from public, anon;
revoke all on function public.is_group_admin(uuid) from public, anon;
revoke all on function public.is_group_owner(uuid) from public, anon;
grant execute on function public.is_group_member(uuid) to authenticated;
grant execute on function public.is_group_admin(uuid) to authenticated;
grant execute on function public.is_group_owner(uuid) to authenticated;

-- Secure RPCs
revoke all on function public.create_group(text, text) from public, anon;
revoke all on function public.create_group_invitation(uuid, timestamptz, integer) from public, anon;
revoke all on function public.revoke_group_invitation(uuid) from public, anon;
revoke all on function public.request_to_join_group(text, text) from public, anon;
revoke all on function public.review_join_request(uuid, text) from public, anon;
revoke all on function public.leave_group(uuid) from public, anon;
revoke all on function public.remove_group_member(uuid, uuid) from public, anon;
revoke all on function public.archive_group(uuid) from public, anon;
revoke all on function public.set_group_member_role(uuid, uuid, text) from public, anon;

grant execute on function public.create_group(text, text) to authenticated;
grant execute on function public.create_group_invitation(uuid, timestamptz, integer) to authenticated;
grant execute on function public.revoke_group_invitation(uuid) to authenticated;
grant execute on function public.request_to_join_group(text, text) to authenticated;
grant execute on function public.review_join_request(uuid, text) to authenticated;
grant execute on function public.leave_group(uuid) to authenticated;
grant execute on function public.remove_group_member(uuid, uuid) to authenticated;
grant execute on function public.archive_group(uuid) to authenticated;
grant execute on function public.set_group_member_role(uuid, uuid, text) to authenticated;

commit;

-- ============================================================
-- PHASE 1 QUICK VERIFICATION
-- Run these separately after applying the migration:
--
-- select table_name
-- from information_schema.tables
-- where table_schema = 'public'
--   and table_name in (
--     'profiles','groups','group_members','group_invitations',
--     'join_requests','audit_logs'
--   )
-- order by table_name;
--
-- select schemaname, tablename, rowsecurity
-- from pg_tables
-- where schemaname = 'public'
--   and tablename in (
--     'profiles','groups','group_members','group_invitations',
--     'join_requests','audit_logs'
--   )
-- order by tablename;
--
-- NOTE: Do not test authenticated RPCs while logged in as the
-- SQL Editor postgres role; test through a real authenticated
-- Supabase client session.
-- ============================================================


-- ============================================================
-- 0002_phase1_hardening.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0002 PHASE 1 HARDENING + SHARED INFRASTRUCTURE
-- Follow-up to 0001 (the supplied Phase 1 foundation is preserved).
-- Adds: internal helpers, rate limiting, richer audit trail,
-- notifications, ownership transfer, archived-group guards,
-- read RPCs for groups/members/requests/invitations/activity,
-- profile privacy (phone hidden from other members).
-- ============================================================

begin;

-- ------------------------------------------------------------
-- 1. Profiles: privacy + tombstones (for account deletion)
-- ------------------------------------------------------------
-- Profiles must outlive auth users so that old ledgers stay readable
-- ("Deleted user"). The FK to auth.users is therefore dropped; the
-- delete_my_account() RPC (migration 0007) anonymises the profile.
alter table public.profiles drop constraint if exists profiles_id_fkey;
alter table public.profiles add column if not exists deleted_at timestamptz;

-- Other members must never see a phone number: column-level SELECT grant
-- without "phone". The user reads their own phone through get_my_profile().
revoke select on public.profiles from authenticated;
grant select (id, full_name, avatar_url, preferred_language, created_at, updated_at, deleted_at)
  on public.profiles to authenticated;

-- Former members stay visible to the people they shared a group with
-- (needed for historical ledgers). Only the viewer must be an ACTIVE member.
drop policy if exists profiles_select_self_or_groupmate on public.profiles;
create policy profiles_select_self_or_groupmate
on public.profiles
for select
to authenticated
using (
  id = (select auth.uid())
  or exists (
    select 1
    from public.group_members mine
    join public.group_members theirs on theirs.group_id = mine.group_id
    where mine.user_id = (select auth.uid())
      and mine.status = 'active'
      and theirs.user_id = profiles.id
  )
);

create or replace function public.validate_profile_row()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.full_name := trim(coalesce(new.full_name, ''));
  if new.deleted_at is null and char_length(new.full_name) not between 1 and 80 then
    raise exception 'INVALID_NAME';
  end if;
  if new.phone is not null then
    new.phone := nullif(trim(new.phone), '');
    if new.phone is not null and new.phone !~ '^[0-9+() -]{6,20}$' then
      raise exception 'INVALID_PHONE';
    end if;
  end if;
  if new.avatar_url is not null then
    new.avatar_url := nullif(trim(new.avatar_url), '');
    if new.avatar_url is not null and (char_length(new.avatar_url) > 500 or new.avatar_url !~ '^https://') then
      raise exception 'INVALID_AVATAR_URL';
    end if;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_profiles_validate on public.profiles;
create trigger trg_profiles_validate
before insert or update on public.profiles
for each row execute function public.validate_profile_row();

-- ------------------------------------------------------------
-- 2. Internal helpers (NOT callable by clients)
-- ------------------------------------------------------------
create or replace function public.try_uuid(p_text text)
returns uuid
language plpgsql
immutable
set search_path = ''
as $$
begin
  return p_text::uuid;
exception when others then
  return null;
end;
$$;

create or replace function public.kh_uid()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_uid uuid := (select auth.uid());
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  return v_uid;
end;
$$;

-- p_min_role: 'member' | 'admin' | 'owner'. Returns the caller's id.
create or replace function public.kh_require_role(p_group_id uuid, p_min_role text default 'member')
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
  v_role text;
begin
  select gm.role into v_role
  from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';

  if v_role is null then
    raise exception 'NOT_A_MEMBER' using errcode = '42501';
  end if;
  if p_min_role = 'admin' and v_role not in ('owner', 'admin') then
    raise exception 'ADMIN_REQUIRED' using errcode = '42501';
  end if;
  if p_min_role = 'owner' and v_role <> 'owner' then
    raise exception 'OWNER_REQUIRED' using errcode = '42501';
  end if;
  return v_uid;
end;
$$;

create or replace function public.kh_require_active_group(p_group_id uuid)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_status text;
begin
  select g.status into v_status from public.groups g where g.id = p_group_id;
  if v_status is null then
    raise exception 'GROUP_NOT_FOUND';
  end if;
  if v_status <> 'active' then
    raise exception 'GROUP_ARCHIVED';
  end if;
end;
$$;

create or replace function public.kh_audit(
  p_group_id uuid, p_action text, p_entity_type text, p_entity_id text,
  p_metadata jsonb default '{}'::jsonb
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.audit_logs (group_id, actor_id, action, entity_type, entity_id, metadata)
  values (p_group_id, (select auth.uid()), p_action, p_entity_type, p_entity_id, coalesce(p_metadata, '{}'::jsonb));
$$;

-- Fixed-window per-user rate limit. Raises RATE_LIMITED when exceeded.
create table if not exists public.rate_limits (
  user_id uuid not null,
  action text not null,
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (user_id, action, window_start)
);
alter table public.rate_limits enable row level security;
revoke all on public.rate_limits from anon, authenticated;

create or replace function public.kh_rate_limit(p_action text, p_max integer, p_window_seconds integer)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
  v_window timestamptz;
  v_hits integer;
begin
  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  insert into public.rate_limits (user_id, action, window_start, hits)
  values (v_uid, p_action, v_window, 1)
  on conflict (user_id, action, window_start)
  do update set hits = public.rate_limits.hits + 1
  returning hits into v_hits;

  delete from public.rate_limits rl
  where rl.user_id = v_uid and rl.window_start < now() - interval '2 days';

  if v_hits > p_max then
    raise exception 'RATE_LIMITED' using errcode = '54000';
  end if;
end;
$$;

-- ------------------------------------------------------------
-- 3. Notifications (in-app) + push tokens
-- ------------------------------------------------------------
create table if not exists public.notifications (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles(id) on delete cascade,
  group_id uuid references public.groups(id) on delete cascade,
  type text not null check (char_length(type) between 1 and 60),
  params jsonb not null default '{}'::jsonb,
  dedupe_key text,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index if not exists uq_notifications_dedupe
  on public.notifications(user_id, dedupe_key) where dedupe_key is not null;
create index if not exists idx_notifications_user_created
  on public.notifications(user_id, id desc);
create index if not exists idx_notifications_user_unread
  on public.notifications(user_id) where read_at is null;

create table if not exists public.push_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  token text not null unique check (char_length(token) between 10 and 300),
  platform text not null check (platform in ('android', 'ios', 'web')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_push_tokens_user on public.push_tokens(user_id);

alter table public.notifications enable row level security;
alter table public.push_tokens enable row level security;

drop policy if exists notifications_select_own on public.notifications;
create policy notifications_select_own on public.notifications
  for select to authenticated using (user_id = (select auth.uid()));

-- push_tokens: no client policies at all (RPC only).
revoke all on public.notifications from anon, authenticated;
revoke all on public.push_tokens from anon, authenticated;
grant select on public.notifications to authenticated;

create or replace function public.kh_notify(
  p_user_id uuid, p_group_id uuid, p_type text,
  p_params jsonb default '{}'::jsonb, p_dedupe_key text default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, group_id, type, params, dedupe_key)
  values (p_user_id, p_group_id, p_type, coalesce(p_params, '{}'::jsonb), p_dedupe_key)
  on conflict (user_id, dedupe_key) where dedupe_key is not null do nothing;
$$;

create or replace function public.kh_notify_admins(
  p_group_id uuid, p_type text, p_params jsonb, p_exclude uuid default null, p_dedupe_prefix text default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  select public.kh_notify(
    gm.user_id, p_group_id, p_type, p_params,
    case when p_dedupe_prefix is null then null else p_dedupe_prefix || ':' || gm.user_id::text end
  )
  from public.group_members gm
  where gm.group_id = p_group_id and gm.status = 'active'
    and gm.role in ('owner', 'admin')
    and gm.user_id is distinct from p_exclude;
$$;

-- ------------------------------------------------------------
-- 4. Richer audit trail (what changed, never secrets)
-- ------------------------------------------------------------
create or replace function public.write_group_audit_log()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new jsonb;
  v_old jsonb;
  v_group_id uuid;
  v_entity_id text;
  v_action text;
  v_metadata jsonb;
  v_changes jsonb;
begin
  if tg_op <> 'DELETE' then v_new := to_jsonb(new) - 'token_hash'; end if;
  if tg_op <> 'INSERT' then v_old := to_jsonb(old) - 'token_hash'; end if;

  v_group_id := coalesce(
    nullif(v_new ->> 'group_id', '')::uuid,
    nullif(v_old ->> 'group_id', '')::uuid,
    nullif(v_new ->> 'id', '')::uuid,
    nullif(v_old ->> 'id', '')::uuid
  );
  v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');
  v_action := lower(tg_op);
  v_metadata := jsonb_build_object('table', tg_table_name, 'operation', v_action);

  if tg_op = 'UPDATE' then
    select coalesce(jsonb_object_agg(n.key, jsonb_build_object('old', v_old -> n.key, 'new', n.value)), '{}'::jsonb)
    into v_changes
    from jsonb_each(v_new) n
    where n.key not in ('updated_at')
      and (v_old -> n.key) is distinct from n.value;
    if v_changes = '{}'::jsonb then
      return new;  -- nothing meaningful changed
    end if;
    v_metadata := v_metadata || jsonb_build_object('changes', v_changes);
  elsif tg_op = 'INSERT' then
    v_metadata := v_metadata || jsonb_build_object('snapshot', v_new - 'updated_at' - 'created_at');
  end if;

  insert into public.audit_logs (group_id, actor_id, action, entity_type, entity_id, metadata)
  values (v_group_id, (select auth.uid()), v_action, tg_table_name, v_entity_id, v_metadata);

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

-- ------------------------------------------------------------
-- 5. Group row validation (timezone, archived groups are frozen)
-- ------------------------------------------------------------
create or replace function public.validate_group_row()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names z where z.name = new.timezone) then
    raise exception 'INVALID_TIMEZONE';
  end if;
  if tg_op = 'UPDATE' and old.status = 'archived'
     and (new.name, new.description, new.timezone) is distinct from (old.name, old.description, old.timezone) then
    raise exception 'GROUP_ARCHIVED';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_groups_validate on public.groups;
create trigger trg_groups_validate
before insert or update on public.groups
for each row execute function public.validate_group_row();

-- ------------------------------------------------------------
-- 6. Invitations: audited, archived groups rejected, rate limited
-- ------------------------------------------------------------
create or replace function public.create_group_invitation(
  p_group_id uuid,
  p_expires_at timestamptz default (now() + interval '7 days'),
  p_max_uses integer default null
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_code text;
  v_id uuid;
begin
  v_uid := public.kh_require_role(p_group_id, 'admin');
  perform public.kh_require_active_group(p_group_id);
  perform public.kh_rate_limit('create_invitation', 30, 3600);

  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'Invitation expiry must be in the future';
  end if;
  if p_expires_at is not null and p_expires_at > now() + interval '366 days' then
    raise exception 'Invitation expiry is too far in the future';
  end if;
  if p_max_uses is not null and (p_max_uses < 1 or p_max_uses > 10000) then
    raise exception 'Maximum uses must be positive';
  end if;

  v_code := encode(extensions.gen_random_bytes(24), 'hex');

  insert into public.group_invitations (group_id, token_hash, created_by, expires_at, max_uses)
  values (
    p_group_id,
    encode(extensions.digest(convert_to(v_code, 'UTF8'), 'sha256'), 'hex'),
    v_uid, p_expires_at, p_max_uses
  )
  returning id into v_id;

  perform public.kh_audit(p_group_id, 'invitation.created', 'group_invitations', v_id::text,
    jsonb_build_object('expires_at', p_expires_at, 'max_uses', p_max_uses));
  return v_code;
end;
$$;

create or replace function public.revoke_group_invitation(p_invitation_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_group_id uuid;
begin
  select gi.group_id into v_group_id from public.group_invitations gi where gi.id = p_invitation_id;
  if v_group_id is null then
    raise exception 'Invitation not found';
  end if;
  perform public.kh_require_role(v_group_id, 'admin');

  update public.group_invitations
  set revoked_at = coalesce(revoked_at, now())
  where id = p_invitation_id;

  perform public.kh_audit(v_group_id, 'invitation.revoked', 'group_invitations', p_invitation_id::text);
end;
$$;

-- ------------------------------------------------------------
-- 7. Join requests: rate limited, admins notified, decisions notified
-- ------------------------------------------------------------
create or replace function public.request_to_join_group(
  p_invitation_code text,
  p_message text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := public.kh_uid();
  v_invitation public.group_invitations%rowtype;
  v_group_status text;
  v_group_name text;
  v_request_id uuid;
  v_hash text;
  v_name text;
begin
  perform public.kh_rate_limit('join_request', 20, 3600);

  if p_invitation_code is null or char_length(p_invitation_code) < 20 then
    raise exception 'Invalid invitation code';
  end if;
  if p_message is not null and char_length(p_message) > 300 then
    raise exception 'Message is too long';
  end if;

  v_hash := encode(extensions.digest(convert_to(trim(p_invitation_code), 'UTF8'), 'sha256'), 'hex');

  select * into v_invitation from public.group_invitations gi where gi.token_hash = v_hash for update;

  if not found
     or v_invitation.revoked_at is not null
     or (v_invitation.expires_at is not null and v_invitation.expires_at <= now())
     or (v_invitation.max_uses is not null and v_invitation.uses_count >= v_invitation.max_uses)
  then
    raise exception 'Invitation is invalid, expired, revoked or fully used';
  end if;

  select g.status, g.name into v_group_status, v_group_name
  from public.groups g where g.id = v_invitation.group_id;

  if v_group_status is distinct from 'active' then
    raise exception 'This group is not accepting join requests';
  end if;

  if exists (
    select 1 from public.group_members gm
    where gm.group_id = v_invitation.group_id and gm.user_id = v_user_id and gm.status = 'active'
  ) then
    raise exception 'You are already an active member';
  end if;

  insert into public.join_requests (group_id, user_id, invitation_id, message)
  values (v_invitation.group_id, v_user_id, v_invitation.id, nullif(trim(p_message), ''))
  on conflict (group_id, user_id) where status = 'pending'
  do update set invitation_id = excluded.invitation_id, message = excluded.message, updated_at = now()
  returning id into v_request_id;

  select p.full_name into v_name from public.profiles p where p.id = v_user_id;
  perform public.kh_notify_admins(
    v_invitation.group_id, 'join_request',
    jsonb_build_object('name', v_name, 'group_name', v_group_name),
    v_user_id, 'join:' || v_request_id::text
  );
  return v_request_id;
end;
$$;

create or replace function public.review_join_request(
  p_request_id uuid,
  p_decision text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request public.join_requests%rowtype;
  v_invitation public.group_invitations%rowtype;
  v_group_name text;
  v_actor uuid := public.kh_uid();
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'Decision must be approved or rejected';
  end if;

  select * into v_request from public.join_requests jr where jr.id = p_request_id for update;
  if not found then
    raise exception 'Join request not found';
  end if;

  perform public.kh_require_role(v_request.group_id, 'admin');

  if v_request.status <> 'pending' then
    raise exception 'This request has already been reviewed';
  end if;

  if p_decision = 'approved' then
    perform public.kh_require_active_group(v_request.group_id);

    select * into v_invitation from public.group_invitations gi
    where gi.id = v_request.invitation_id for update;

    if v_invitation.revoked_at is not null then
      raise exception 'The invitation has been revoked';
    end if;
    if v_invitation.max_uses is not null and v_invitation.uses_count >= v_invitation.max_uses then
      raise exception 'Invitation usage limit reached';
    end if;

    insert into public.group_members (group_id, user_id, role, status)
    values (v_request.group_id, v_request.user_id, 'member', 'active')
    on conflict (group_id, user_id) where status = 'active' do nothing;

    update public.group_invitations set uses_count = uses_count + 1 where id = v_invitation.id;
  end if;

  update public.join_requests
  set status = p_decision, reviewed_by = v_actor, reviewed_at = now(), updated_at = now()
  where id = p_request_id;

  select g.name into v_group_name from public.groups g where g.id = v_request.group_id;
  perform public.kh_notify(
    v_request.user_id, v_request.group_id,
    case when p_decision = 'approved' then 'join_approved' else 'join_rejected' end,
    jsonb_build_object('group_name', v_group_name), null
  );
end;
$$;

create or replace function public.cancel_join_request(p_request_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
  v_req public.join_requests%rowtype;
begin
  select * into v_req from public.join_requests jr where jr.id = p_request_id for update;
  if not found or v_req.user_id <> v_uid then
    raise exception 'Join request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'This request has already been reviewed';
  end if;
  update public.join_requests
  set status = 'cancelled', reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
  where id = p_request_id;
end;
$$;

-- ------------------------------------------------------------
-- 8. Ownership transfer (atomic + audited) and group update
-- ------------------------------------------------------------
create or replace function public.transfer_group_ownership(p_group_id uuid, p_new_owner uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid;
  v_group_name text;
  v_actor_name text;
begin
  v_actor := public.kh_require_role(p_group_id, 'owner');
  perform public.kh_require_active_group(p_group_id);

  if p_new_owner = v_actor then
    raise exception 'ALREADY_OWNER';
  end if;

  -- lock both rows in a stable order to avoid deadlocks
  perform 1 from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id in (v_actor, p_new_owner) and gm.status = 'active'
  order by gm.user_id for update;

  if not exists (
    select 1 from public.group_members gm
    where gm.group_id = p_group_id and gm.user_id = p_new_owner and gm.status = 'active'
  ) then
    raise exception 'Active target membership not found';
  end if;

  -- the partial unique index allows zero owners momentarily, so demote first
  update public.group_members set role = 'admin'
  where group_id = p_group_id and user_id = v_actor and status = 'active' and role = 'owner';

  update public.group_members set role = 'owner'
  where group_id = p_group_id and user_id = p_new_owner and status = 'active';

  perform public.kh_audit(p_group_id, 'group.ownership_transferred', 'groups', p_group_id::text,
    jsonb_build_object('from', v_actor, 'to', p_new_owner));

  select g.name into v_group_name from public.groups g where g.id = p_group_id;
  select p.full_name into v_actor_name from public.profiles p where p.id = v_actor;
  perform public.kh_notify(p_new_owner, p_group_id, 'ownership_received',
    jsonb_build_object('group_name', v_group_name, 'name', v_actor_name), null);
end;
$$;

create or replace function public.update_group(
  p_group_id uuid, p_name text, p_description text default null, p_timezone text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'admin');
  perform public.kh_require_active_group(p_group_id);
  if p_name is null or char_length(trim(p_name)) not between 2 and 80 then
    raise exception 'Group name must be between 2 and 80 characters';
  end if;
  if p_description is not null and char_length(p_description) > 500 then
    raise exception 'Description is too long';
  end if;
  update public.groups
  set name = trim(p_name),
      description = nullif(trim(coalesce(p_description, '')), ''),
      timezone = coalesce(nullif(trim(p_timezone), ''), timezone)
  where id = p_group_id;
end;
$$;

-- ------------------------------------------------------------
-- 9. Read RPCs (SECURITY DEFINER with explicit membership checks)
-- ------------------------------------------------------------
create or replace function public.get_my_profile()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  return (
    select jsonb_build_object(
      'id', p.id, 'full_name', p.full_name, 'phone', p.phone,
      'avatar_url', p.avatar_url, 'preferred_language', p.preferred_language
    )
    from public.profiles p where p.id = v_uid
  );
end;
$$;

create or replace function public.update_my_profile(
  p_full_name text, p_phone text default null, p_avatar_url text default null,
  p_preferred_language text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  if p_preferred_language is not null and p_preferred_language not in ('en', 'hi') then
    raise exception 'INVALID_LANGUAGE';
  end if;
  update public.profiles p
  set full_name = p_full_name,
      phone = p_phone,
      avatar_url = p_avatar_url,
      preferred_language = coalesce(p_preferred_language, p.preferred_language)
  where p.id = v_uid and p.deleted_at is null;
end;
$$;

create or replace function public.list_my_groups()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', g.id, 'name', g.name, 'description', g.description, 'status', g.status,
      'currency_code', g.currency_code, 'timezone', g.timezone,
      'role', gm.role, 'created_at', g.created_at,
      'member_count', (select count(*) from public.group_members m where m.group_id = g.id and m.status = 'active')
    ) order by g.status, g.created_at desc)
    from public.group_members gm
    join public.groups g on g.id = gm.group_id
    where gm.user_id = v_uid and gm.status = 'active'
  ), '[]'::jsonb);
end;
$$;

create or replace function public.get_group(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_require_role(p_group_id, 'member');
  v_role text;
begin
  select gm.role into v_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';

  return (
    select jsonb_build_object(
      'id', g.id, 'name', g.name, 'description', g.description, 'status', g.status,
      'currency_code', g.currency_code, 'timezone', g.timezone, 'created_at', g.created_at,
      'my_role', v_role,
      'member_count', (select count(*) from public.group_members m where m.group_id = g.id and m.status = 'active'),
      'pending_requests', case when v_role in ('owner', 'admin')
        then (select count(*) from public.join_requests jr where jr.group_id = g.id and jr.status = 'pending') else 0 end
    )
    from public.groups g where g.id = p_group_id
  );
end;
$$;

create or replace function public.list_group_members(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'member');
  return coalesce((
    select jsonb_agg(x.j order by x.is_active desc, x.role_rank, x.lname)
    from (
      select distinct on (gm.user_id)
        (gm.status = 'active') as is_active,
        case gm.role when 'owner' then 0 when 'admin' then 1 else 2 end as role_rank,
        lower(p.full_name) as lname,
        jsonb_build_object(
          'user_id', gm.user_id, 'full_name', p.full_name, 'avatar_url', p.avatar_url,
          'is_deleted', p.deleted_at is not null,
          'role', gm.role, 'status', gm.status, 'joined_at', gm.joined_at, 'left_at', gm.left_at
        ) as j
      from public.group_members gm
      join public.profiles p on p.id = gm.user_id
      where gm.group_id = p_group_id
      order by gm.user_id, (gm.status = 'active') desc, gm.joined_at desc
    ) x
  ), '[]'::jsonb);
end;
$$;

create or replace function public.list_join_requests(p_group_id uuid, p_status text default 'pending')
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'admin');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', jr.id, 'user_id', jr.user_id, 'full_name', p.full_name, 'message', jr.message,
      'status', jr.status, 'created_at', jr.created_at, 'reviewed_at', jr.reviewed_at
    ) order by jr.created_at desc)
    from public.join_requests jr
    join public.profiles p on p.id = jr.user_id
    where jr.group_id = p_group_id and (p_status is null or jr.status = p_status)
  ), '[]'::jsonb);
end;
$$;

create or replace function public.list_my_join_requests()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', jr.id, 'group_id', jr.group_id, 'group_name', g.name, 'status', jr.status,
      'message', jr.message, 'created_at', jr.created_at
    ) order by jr.created_at desc)
    from public.join_requests jr
    join public.groups g on g.id = jr.group_id
    where jr.user_id = v_uid
      and jr.created_at > now() - interval '60 days'
  ), '[]'::jsonb);
end;
$$;

create or replace function public.list_group_invitations(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'admin');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', gi.id, 'created_at', gi.created_at, 'expires_at', gi.expires_at,
      'max_uses', gi.max_uses, 'uses_count', gi.uses_count, 'revoked_at', gi.revoked_at,
      'created_by_name', p.full_name,
      'state', case
        when gi.revoked_at is not null then 'revoked'
        when gi.expires_at is not null and gi.expires_at <= now() then 'expired'
        when gi.max_uses is not null and gi.uses_count >= gi.max_uses then 'used_up'
        else 'active' end
    ) order by gi.created_at desc)
    from public.group_invitations gi
    join public.profiles p on p.id = gi.created_by
    where gi.group_id = p_group_id
  ), '[]'::jsonb);
end;
$$;

create or replace function public.list_group_activity(
  p_group_id uuid, p_limit integer default 40, p_before_id bigint default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 40), 1), 100);
  v_items jsonb;
begin
  perform public.kh_require_role(p_group_id, 'member');
  select coalesce(jsonb_agg(t.j order by t.id desc), '[]'::jsonb) into v_items
  from (
    select al.id, jsonb_build_object(
      'id', al.id, 'action', al.action, 'entity_type', al.entity_type, 'entity_id', al.entity_id,
      'actor_id', al.actor_id, 'actor_name', p.full_name, 'metadata', al.metadata, 'created_at', al.created_at
    ) as j
    from public.audit_logs al
    left join public.profiles p on p.id = al.actor_id
    where al.group_id = p_group_id
      and (p_before_id is null or al.id < p_before_id)
    order by al.id desc
    limit v_limit
  ) t;
  return jsonb_build_object(
    'items', v_items,
    'next_before_id', case when jsonb_array_length(v_items) = v_limit
      then (v_items -> (v_limit - 1) ->> 'id')::bigint else null end
  );
end;
$$;

-- Notifications
create or replace function public.list_notifications(p_limit integer default 30, p_before_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_items jsonb;
begin
  select coalesce(jsonb_agg(t.j order by t.id desc), '[]'::jsonb) into v_items
  from (
    select n.id, jsonb_build_object(
      'id', n.id, 'group_id', n.group_id, 'type', n.type, 'params', n.params,
      'read_at', n.read_at, 'created_at', n.created_at
    ) as j
    from public.notifications n
    where n.user_id = v_uid and (p_before_id is null or n.id < p_before_id)
    order by n.id desc
    limit v_limit
  ) t;
  return jsonb_build_object(
    'items', v_items,
    'unread_count', (select count(*) from public.notifications n where n.user_id = v_uid and n.read_at is null),
    'next_before_id', case when jsonb_array_length(v_items) = v_limit
      then (v_items -> (v_limit - 1) ->> 'id')::bigint else null end
  );
end;
$$;

create or replace function public.mark_notifications_read(p_ids bigint[] default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  update public.notifications n
  set read_at = now()
  where n.user_id = v_uid and n.read_at is null
    and (p_ids is null or n.id = any (p_ids));
end;
$$;

create or replace function public.register_push_token(p_token text, p_platform text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  perform public.kh_rate_limit('push_token', 30, 3600);
  insert into public.push_tokens (user_id, token, platform)
  values (v_uid, p_token, p_platform)
  on conflict (token) do update set user_id = v_uid, platform = excluded.platform, updated_at = now();
end;
$$;

create or replace function public.unregister_push_token(p_token text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  delete from public.push_tokens where token = p_token and user_id = v_uid;
end;
$$;

-- ------------------------------------------------------------
-- 10. Privileges
-- ------------------------------------------------------------
-- Internal helpers: nobody but the function owner / other definer functions.
revoke all on function public.try_uuid(text) from public, anon;
grant execute on function public.try_uuid(text) to authenticated;
revoke all on function public.kh_uid() from public, anon, authenticated;
revoke all on function public.kh_require_role(uuid, text) from public, anon, authenticated;
revoke all on function public.kh_require_active_group(uuid) from public, anon, authenticated;
revoke all on function public.kh_audit(uuid, text, text, text, jsonb) from public, anon, authenticated;
revoke all on function public.kh_rate_limit(text, integer, integer) from public, anon, authenticated;
revoke all on function public.kh_notify(uuid, uuid, text, jsonb, text) from public, anon, authenticated;
revoke all on function public.kh_notify_admins(uuid, text, jsonb, uuid, text) from public, anon, authenticated;
revoke all on function public.write_group_audit_log() from public, anon, authenticated;
revoke all on function public.validate_profile_row() from public, anon, authenticated;
revoke all on function public.validate_group_row() from public, anon, authenticated;
revoke all on function public.set_updated_at() from public, anon, authenticated;
revoke all on function public.handle_new_user() from public, anon, authenticated;

-- Client-callable RPCs.
revoke all on function public.create_group_invitation(uuid, timestamptz, integer) from public, anon;
revoke all on function public.revoke_group_invitation(uuid) from public, anon;
revoke all on function public.request_to_join_group(text, text) from public, anon;
revoke all on function public.review_join_request(uuid, text) from public, anon;
revoke all on function public.cancel_join_request(uuid) from public, anon;
revoke all on function public.transfer_group_ownership(uuid, uuid) from public, anon;
revoke all on function public.update_group(uuid, text, text, text) from public, anon;
revoke all on function public.get_my_profile() from public, anon;
revoke all on function public.update_my_profile(text, text, text, text) from public, anon;
revoke all on function public.list_my_groups() from public, anon;
revoke all on function public.get_group(uuid) from public, anon;
revoke all on function public.list_group_members(uuid) from public, anon;
revoke all on function public.list_join_requests(uuid, text) from public, anon;
revoke all on function public.list_my_join_requests() from public, anon;
revoke all on function public.list_group_invitations(uuid) from public, anon;
revoke all on function public.list_group_activity(uuid, integer, bigint) from public, anon;
revoke all on function public.list_notifications(integer, bigint) from public, anon;
revoke all on function public.mark_notifications_read(bigint[]) from public, anon;
revoke all on function public.register_push_token(text, text) from public, anon;
revoke all on function public.unregister_push_token(text) from public, anon;

grant execute on function public.create_group_invitation(uuid, timestamptz, integer) to authenticated;
grant execute on function public.revoke_group_invitation(uuid) to authenticated;
grant execute on function public.request_to_join_group(text, text) to authenticated;
grant execute on function public.review_join_request(uuid, text) to authenticated;
grant execute on function public.cancel_join_request(uuid) to authenticated;
grant execute on function public.transfer_group_ownership(uuid, uuid) to authenticated;
grant execute on function public.update_group(uuid, text, text, text) to authenticated;
grant execute on function public.get_my_profile() to authenticated;
grant execute on function public.update_my_profile(text, text, text, text) to authenticated;
grant execute on function public.list_my_groups() to authenticated;
grant execute on function public.get_group(uuid) to authenticated;
grant execute on function public.list_group_members(uuid) to authenticated;
grant execute on function public.list_join_requests(uuid, text) to authenticated;
grant execute on function public.list_my_join_requests() to authenticated;
grant execute on function public.list_group_invitations(uuid) to authenticated;
grant execute on function public.list_group_activity(uuid, integer, bigint) to authenticated;
grant execute on function public.list_notifications(integer, bigint) to authenticated;
grant execute on function public.mark_notifications_read(bigint[]) to authenticated;
grant execute on function public.register_push_token(text, text) to authenticated;
grant execute on function public.unregister_push_token(text) to authenticated;

commit;


-- ============================================================
-- 0003_expenses.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0003 EXPENSE DIARY
-- categories, expenses, immutable split snapshots, revisions,
-- receipts, budgets, deterministic split engine, transactional RPCs.
-- Money is ALWAYS integer paise (bigint). Max single amount: 10,000,000,000
-- paise (INR 10 crore) so that amount * 10000 (basis points) stays far below
-- the bigint limit and JavaScript's safe-integer limit.
-- ============================================================

begin;

-- ------------------------------------------------------------
-- 1. Categories (system defined, read-only for clients)
-- ------------------------------------------------------------
create table if not exists public.expense_categories (
  key text primary key check (key ~ '^[a-z_]{2,30}$'),
  name_en text not null,
  name_hi text not null,
  sort_order integer not null default 0
);

insert into public.expense_categories (key, name_en, name_hi, sort_order) values
  ('rent',        'Rent',        'किराया',     10),
  ('grocery',     'Grocery',     'किराना',     20),
  ('food',        'Food',        'खाना',       30),
  ('electricity', 'Electricity', 'बिजली',      40),
  ('water',       'Water',       'पानी',       50),
  ('gas',         'Gas',         'गैस',        60),
  ('internet',    'Internet',    'इंटरनेट',    70),
  ('cleaning',    'Cleaning',    'सफाई',       80),
  ('travel',      'Travel',      'यात्रा',     90),
  ('other',       'Other',       'अन्य',       100)
on conflict (key) do update
  set name_en = excluded.name_en, name_hi = excluded.name_hi, sort_order = excluded.sort_order;

-- ------------------------------------------------------------
-- 2. Expenses and immutable split snapshots
-- ------------------------------------------------------------
create table if not exists public.expenses (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete restrict,
  title text not null check (char_length(trim(title)) between 1 and 120),
  amount_paise bigint not null check (amount_paise > 0 and amount_paise <= 10000000000),
  category_key text not null references public.expense_categories(key),
  spent_at timestamptz not null,
  paid_by uuid not null references public.profiles(id),
  split_mode text not null check (split_mode in ('equal', 'amount', 'percent')),
  note text check (note is null or char_length(note) <= 500),
  status text not null default 'active' check (status in ('active', 'voided')),
  version integer not null default 1 check (version >= 1),
  idempotency_key uuid not null,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id),
  void_reason text,
  voided_at timestamptz,
  voided_by uuid references public.profiles(id),
  unique (id, group_id),
  unique (group_id, created_by, idempotency_key),
  check ((status = 'voided') = (voided_at is not null))
);
create index if not exists idx_expenses_group_spent on public.expenses(group_id, spent_at desc, id desc);
create index if not exists idx_expenses_group_payer on public.expenses(group_id, paid_by);
create index if not exists idx_expenses_group_status_spent on public.expenses(group_id, status, spent_at);

create table if not exists public.expense_splits (
  id uuid primary key default gen_random_uuid(),
  expense_id uuid not null,
  group_id uuid not null,
  version integer not null check (version >= 1),
  user_id uuid not null references public.profiles(id),
  share_paise bigint not null check (share_paise >= 0),
  percent_bps integer check (percent_bps is null or percent_bps between 0 and 10000),
  created_at timestamptz not null default now(),
  foreign key (expense_id, group_id) references public.expenses(id, group_id) on delete restrict,
  unique (expense_id, version, user_id)
);
create index if not exists idx_expense_splits_expense on public.expense_splits(expense_id, version);
create index if not exists idx_expense_splits_group_user on public.expense_splits(group_id, user_id);

create table if not exists public.expense_revisions (
  id bigint generated always as identity primary key,
  expense_id uuid not null,
  group_id uuid not null,
  version integer not null,
  change_type text not null check (change_type in ('edit', 'void')),
  reason text not null check (char_length(trim(reason)) between 3 and 300),
  snapshot jsonb not null,
  changed_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  foreign key (expense_id, group_id) references public.expenses(id, group_id) on delete restrict
);
create index if not exists idx_expense_revisions_expense on public.expense_revisions(expense_id, id desc);

create table if not exists public.expense_receipts (
  id uuid primary key default gen_random_uuid(),
  expense_id uuid not null,
  group_id uuid not null,
  storage_path text not null unique check (char_length(storage_path) <= 400),
  file_name text not null check (char_length(file_name) between 1 and 200),
  mime_type text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf')),
  size_bytes integer not null check (size_bytes between 1 and 5242880),
  uploaded_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  removed_at timestamptz,
  removed_by uuid references public.profiles(id),
  foreign key (expense_id, group_id) references public.expenses(id, group_id) on delete restrict
);
create index if not exists idx_expense_receipts_expense on public.expense_receipts(expense_id);

create table if not exists public.group_budgets (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  category_key text references public.expense_categories(key),
  amount_paise bigint not null check (amount_paise > 0 and amount_paise <= 10000000000),
  created_by uuid not null references public.profiles(id),
  updated_by uuid references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists uq_group_budget_scope
  on public.group_budgets(group_id, coalesce(category_key, '__all__'));

-- ------------------------------------------------------------
-- 3. Integrity triggers (defence in depth; clients cannot write anyway)
-- ------------------------------------------------------------
create or replace function public.kh_user_in_group(p_group_id uuid, p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.group_members gm where gm.group_id = p_group_id and gm.user_id = p_user_id);
$$;

create or replace function public.enforce_expense_members()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not public.kh_user_in_group(new.group_id, new.paid_by) then
    raise exception 'PAYER_NOT_MEMBER';
  end if;
  if not public.kh_user_in_group(new.group_id, new.created_by) then
    raise exception 'NOT_A_MEMBER';
  end if;
  return new;
end;
$$;

create or replace function public.enforce_split_member()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not public.kh_user_in_group(new.group_id, new.user_id) then
    raise exception 'PARTICIPANT_NOT_MEMBER';
  end if;
  return new;
end;
$$;

create or replace function public.block_hard_delete()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'HARD_DELETE_FORBIDDEN' using hint = 'Financial records are void/reverse only.';
end;
$$;

create or replace function public.block_row_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'IMMUTABLE_RECORD';
end;
$$;

create or replace function public.guard_expense_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare v_fin_changed boolean;
begin
  if old.status = 'voided' then
    raise exception 'EXPENSE_VOIDED';
  end if;
  if new.group_id <> old.group_id or new.created_by <> old.created_by
     or new.idempotency_key <> old.idempotency_key or new.created_at <> old.created_at then
    raise exception 'IMMUTABLE_RECORD';
  end if;

  v_fin_changed := (new.title, new.amount_paise, new.category_key, new.spent_at, new.paid_by, new.split_mode, new.note)
    is distinct from (old.title, old.amount_paise, old.category_key, old.spent_at, old.paid_by, old.split_mode, old.note);

  if new.status = 'voided' then
    if v_fin_changed or new.version <> old.version then
      raise exception 'IMMUTABLE_RECORD';
    end if;
  elsif v_fin_changed then
    if new.version <> old.version + 1 then
      raise exception 'VERSION_CONFLICT';
    end if;
  elsif new.version <> old.version then
    raise exception 'VERSION_CONFLICT';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

-- Split shares of the current version must sum exactly to the amount (checked at COMMIT).
create or replace function public.check_expense_split_sum()
returns trigger
language plpgsql
set search_path = ''
as $$
declare v_sum bigint; v_cnt integer;
begin
  select coalesce(sum(es.share_paise), 0), count(*) into v_sum, v_cnt
  from public.expense_splits es where es.expense_id = new.id and es.version = new.version;
  if v_cnt = 0 then raise exception 'NO_PARTICIPANTS'; end if;
  if v_sum <> new.amount_paise then raise exception 'SPLIT_SUM_MISMATCH'; end if;
  return null;
end;
$$;

drop trigger if exists trg_expenses_members on public.expenses;
create trigger trg_expenses_members before insert or update on public.expenses
  for each row execute function public.enforce_expense_members();
drop trigger if exists trg_expenses_guard on public.expenses;
create trigger trg_expenses_guard before update on public.expenses
  for each row execute function public.guard_expense_update();
drop trigger if exists trg_expenses_no_delete on public.expenses;
create trigger trg_expenses_no_delete before delete on public.expenses
  for each row execute function public.block_hard_delete();
drop trigger if exists trg_expenses_split_sum on public.expenses;
create constraint trigger trg_expenses_split_sum after insert or update on public.expenses
  deferrable initially deferred for each row execute function public.check_expense_split_sum();

drop trigger if exists trg_splits_member on public.expense_splits;
create trigger trg_splits_member before insert on public.expense_splits
  for each row execute function public.enforce_split_member();
drop trigger if exists trg_splits_immutable on public.expense_splits;
create trigger trg_splits_immutable before update on public.expense_splits
  for each row execute function public.block_row_update();
drop trigger if exists trg_splits_no_delete on public.expense_splits;
create trigger trg_splits_no_delete before delete on public.expense_splits
  for each row execute function public.block_hard_delete();

drop trigger if exists trg_revisions_immutable on public.expense_revisions;
create trigger trg_revisions_immutable before update on public.expense_revisions
  for each row execute function public.block_row_update();
drop trigger if exists trg_revisions_no_delete on public.expense_revisions;
create trigger trg_revisions_no_delete before delete on public.expense_revisions
  for each row execute function public.block_hard_delete();

drop trigger if exists trg_receipts_no_delete on public.expense_receipts;
create trigger trg_receipts_no_delete before delete on public.expense_receipts
  for each row execute function public.block_hard_delete();

drop trigger if exists trg_budgets_updated_at on public.group_budgets;
create trigger trg_budgets_updated_at before update on public.group_budgets
  for each row execute function public.set_updated_at();

-- ------------------------------------------------------------
-- 4. The split engine (exact integer arithmetic, deterministic remainder)
-- ------------------------------------------------------------
-- p_participants: jsonb array of
--   equal   : {"user_id": uuid}
--   amount  : {"user_id": uuid, "amount_paise": integer}
--   percent : {"user_id": uuid, "percent_bps": integer}   (100.00% = 10000)
-- Remainders: equal -> first N participants ordered by user_id get +1 paise.
--             percent -> largest-remainder method, ties broken by user_id.
create or replace function public.compute_splits(
  p_mode text, p_amount_paise bigint, p_participants jsonb
)
returns table (user_id uuid, share_paise bigint, percent_bps integer)
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_n integer;
  v_distinct integer;
  v_sum bigint;
  v_leftover bigint;
begin
  if p_mode is null or p_mode not in ('equal', 'amount', 'percent') then
    raise exception 'INVALID_SPLIT_MODE';
  end if;
  if p_amount_paise is null or p_amount_paise <= 0 or p_amount_paise > 10000000000 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if p_participants is null or jsonb_typeof(p_participants) <> 'array'
     or jsonb_array_length(p_participants) = 0 then
    raise exception 'NO_PARTICIPANTS';
  end if;
  if jsonb_array_length(p_participants) > 1000 then
    raise exception 'TOO_MANY_PARTICIPANTS';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_participants) e
    where jsonb_typeof(e) <> 'object' or public.try_uuid(e ->> 'user_id') is null
  ) then
    raise exception 'INVALID_PARTICIPANT';
  end if;

  select count(*), count(distinct (e ->> 'user_id')::uuid) into v_n, v_distinct
  from jsonb_array_elements(p_participants) e;
  if v_n <> v_distinct then
    raise exception 'DUPLICATE_PARTICIPANT';
  end if;

  if p_mode = 'equal' then
    return query
      select r.uid,
             (p_amount_paise / v_n) + case when r.rn <= (p_amount_paise % v_n) then 1 else 0 end,
             null::integer
      from (
        select (e ->> 'user_id')::uuid as uid,
               row_number() over (order by (e ->> 'user_id')::uuid) as rn
        from jsonb_array_elements(p_participants) e
      ) r
      order by r.uid;

  elsif p_mode = 'amount' then
    if exists (
      select 1 from jsonb_array_elements(p_participants) e
      where (e ->> 'amount_paise') is null or (e ->> 'amount_paise') !~ '^[0-9]{1,11}$'
    ) then
      raise exception 'INVALID_SPLIT';
    end if;
    select sum((e ->> 'amount_paise')::bigint) into v_sum from jsonb_array_elements(p_participants) e;
    if v_sum <> p_amount_paise then
      raise exception 'SPLIT_SUM_MISMATCH';
    end if;
    return query
      select (e ->> 'user_id')::uuid, (e ->> 'amount_paise')::bigint, null::integer
      from jsonb_array_elements(p_participants) e
      order by 1;

  else -- percent
    if exists (
      select 1 from jsonb_array_elements(p_participants) e
      where (e ->> 'percent_bps') is null or (e ->> 'percent_bps') !~ '^[0-9]{1,5}$'
         or (e ->> 'percent_bps')::integer > 10000
    ) then
      raise exception 'INVALID_SPLIT';
    end if;
    select sum((e ->> 'percent_bps')::bigint) into v_sum from jsonb_array_elements(p_participants) e;
    if v_sum <> 10000 then
      raise exception 'PERCENT_SUM_INVALID';
    end if;
    select p_amount_paise - sum((p_amount_paise * (e ->> 'percent_bps')::bigint) / 10000)
    into v_leftover from jsonb_array_elements(p_participants) e;

    return query
      select x.uid, x.fl + case when x.rk <= v_leftover then 1 else 0 end, x.bps
      from (
        select s.uid, s.bps, s.fl,
               row_number() over (order by s.rem desc, s.uid) as rk
        from (
          select (e ->> 'user_id')::uuid as uid,
                 (e ->> 'percent_bps')::integer as bps,
                 (p_amount_paise * (e ->> 'percent_bps')::bigint) / 10000 as fl,
                 (p_amount_paise * (e ->> 'percent_bps')::bigint) % 10000 as rem
          from jsonb_array_elements(p_participants) e
        ) s
      ) x
      order by x.uid;
  end if;
end;
$$;

-- ------------------------------------------------------------
-- 5. Budget alerts (in-app, once per level per month)
-- ------------------------------------------------------------
create or replace function public.kh_check_budgets(p_group_id uuid, p_spent_at timestamptz)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tz text;
  v_local_month timestamp;
  v_start timestamptz;
  v_end timestamptz;
  v_month text;
  b record;
  v_spent bigint;
  v_level integer;
begin
  select g.timezone into v_tz from public.groups g where g.id = p_group_id;
  v_local_month := date_trunc('month', p_spent_at at time zone v_tz);
  v_start := v_local_month at time zone v_tz;
  v_end := (v_local_month + interval '1 month') at time zone v_tz;
  v_month := to_char(v_local_month, 'YYYY-MM');

  for b in select gb.id, gb.category_key, gb.amount_paise from public.group_budgets gb where gb.group_id = p_group_id loop
    select coalesce(sum(e.amount_paise), 0) into v_spent
    from public.expenses e
    where e.group_id = p_group_id and e.status = 'active'
      and e.spent_at >= v_start and e.spent_at < v_end
      and (b.category_key is null or e.category_key = b.category_key);

    v_level := case
      when v_spent >= b.amount_paise then 100
      when v_spent * 100 >= b.amount_paise * 80 then 80
      else 0 end;

    if v_level > 0 then
      perform public.kh_notify_admins(
        p_group_id, 'budget_alert',
        jsonb_build_object('category_key', b.category_key, 'level', v_level,
                           'spent_paise', v_spent, 'budget_paise', b.amount_paise, 'month', v_month),
        null, 'budget' || v_level || ':' || b.id::text || ':' || v_month
      );
    end if;
  end loop;
end;
$$;

-- Shared validation for create/edit. p_expense_id is null on create; on edit,
-- people already on the expense stay valid even if they have left the group since.
create or replace function public.kh_validate_expense_input(
  p_group_id uuid, p_expense_id uuid, p_title text, p_amount_paise bigint, p_category_key text,
  p_spent_at timestamptz, p_paid_by uuid, p_participants jsonb, p_note text
)
returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_title is null or char_length(trim(p_title)) not between 1 and 120 then
    raise exception 'INVALID_TITLE';
  end if;
  if p_amount_paise is null or p_amount_paise <= 0 or p_amount_paise > 10000000000 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if p_note is not null and char_length(p_note) > 500 then
    raise exception 'NOTE_TOO_LONG';
  end if;
  if not exists (select 1 from public.expense_categories c where c.key = p_category_key) then
    raise exception 'INVALID_CATEGORY';
  end if;
  if p_spent_at is null or p_spent_at > now() + interval '1 day' or p_spent_at < now() - interval '10 years' then
    raise exception 'INVALID_DATE';
  end if;

  if not exists (
    select 1 from public.group_members gm
    where gm.group_id = p_group_id and gm.user_id = p_paid_by and gm.status = 'active'
  ) and not (
    p_expense_id is not null and exists (
      select 1 from public.expenses e where e.id = p_expense_id and e.paid_by = p_paid_by
    )
  ) then
    raise exception 'PAYER_NOT_MEMBER';
  end if;

  if p_participants is null or jsonb_typeof(p_participants) <> 'array' then
    raise exception 'NO_PARTICIPANTS';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_participants) pe
    where public.try_uuid(pe ->> 'user_id') is not null
      and not exists (
        select 1 from public.group_members gm
        where gm.group_id = p_group_id and gm.user_id = (pe ->> 'user_id')::uuid and gm.status = 'active'
      )
      and not (
        p_expense_id is not null and exists (
          select 1 from public.expense_splits es
          join public.expenses e on e.id = es.expense_id and e.version = es.version
          where es.expense_id = p_expense_id and es.user_id = (pe ->> 'user_id')::uuid
        )
      )
  ) then
    raise exception 'PARTICIPANT_NOT_MEMBER';
  end if;
end;
$$;

-- ------------------------------------------------------------
-- 6. Write RPCs
-- ------------------------------------------------------------
create or replace function public.create_expense(
  p_group_id uuid,
  p_idempotency_key uuid,
  p_title text,
  p_amount_paise bigint,
  p_category_key text,
  p_spent_at timestamptz,
  p_paid_by uuid,
  p_split_mode text,
  p_participants jsonb,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_id uuid;
  v_name text;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  if p_idempotency_key is null then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED';
  end if;

  -- Idempotent replay: same key from same user in same group returns the original expense.
  select e.id into v_id from public.expenses e
  where e.group_id = p_group_id and e.created_by = v_uid and e.idempotency_key = p_idempotency_key;
  if v_id is not null then
    return v_id;
  end if;

  perform public.kh_rate_limit('create_expense', 300, 3600);
  perform public.kh_validate_expense_input(
    p_group_id, null, p_title, p_amount_paise, p_category_key, p_spent_at, p_paid_by, p_participants, p_note);

  -- compute first so invalid splits fail before anything is written
  perform 1 from public.compute_splits(p_split_mode, p_amount_paise, p_participants);

  insert into public.expenses (
    group_id, title, amount_paise, category_key, spent_at, paid_by, split_mode, note,
    idempotency_key, created_by, updated_by
  )
  values (
    p_group_id, trim(p_title), p_amount_paise, p_category_key, p_spent_at, p_paid_by, p_split_mode,
    nullif(trim(coalesce(p_note, '')), ''), p_idempotency_key, v_uid, v_uid
  )
  on conflict (group_id, created_by, idempotency_key) do nothing
  returning id into v_id;

  if v_id is null then  -- lost a race with an identical concurrent request
    select e.id into v_id from public.expenses e
    where e.group_id = p_group_id and e.created_by = v_uid and e.idempotency_key = p_idempotency_key;
    return v_id;
  end if;

  insert into public.expense_splits (expense_id, group_id, version, user_id, share_paise, percent_bps)
  select v_id, p_group_id, 1, s.user_id, s.share_paise, s.percent_bps
  from public.compute_splits(p_split_mode, p_amount_paise, p_participants) s;

  perform public.kh_audit(p_group_id, 'expense.created', 'expenses', v_id::text,
    jsonb_build_object('title', trim(p_title), 'amount_paise', p_amount_paise, 'paid_by', p_paid_by,
                       'split_mode', p_split_mode, 'category_key', p_category_key));

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  perform public.kh_notify(
    es.user_id, p_group_id, 'expense_added',
    jsonb_build_object('title', trim(p_title), 'amount_paise', p_amount_paise,
                       'share_paise', es.share_paise, 'name', v_name, 'expense_id', v_id), null)
  from public.expense_splits es
  where es.expense_id = v_id and es.version = 1 and es.user_id <> v_uid and es.share_paise > 0;

  perform public.kh_check_budgets(p_group_id, p_spent_at);
  return v_id;
end;
$$;

create or replace function public.edit_expense(
  p_expense_id uuid,
  p_expected_version integer,
  p_reason text,
  p_title text,
  p_amount_paise bigint,
  p_category_key text,
  p_spent_at timestamptz,
  p_paid_by uuid,
  p_split_mode text,
  p_participants jsonb,
  p_note text default null
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_exp public.expenses%rowtype;
  v_role text;
  v_new_version integer;
  v_name text;
  v_old_splits jsonb;
begin
  select * into v_exp from public.expenses e where e.id = p_expense_id for update;
  if not found then
    raise exception 'EXPENSE_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_exp.group_id, 'member');
  perform public.kh_require_active_group(v_exp.group_id);

  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_exp.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_exp.created_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  if v_exp.status <> 'active' then
    raise exception 'EXPENSE_VOIDED';
  end if;
  if p_expected_version is distinct from v_exp.version then
    raise exception 'VERSION_CONFLICT';
  end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 or char_length(p_reason) > 300 then
    raise exception 'REASON_REQUIRED';
  end if;

  perform public.kh_rate_limit('edit_expense', 200, 3600);
  perform public.kh_validate_expense_input(
    v_exp.group_id, p_expense_id, p_title, p_amount_paise, p_category_key, p_spent_at, p_paid_by, p_participants, p_note);
  perform 1 from public.compute_splits(p_split_mode, p_amount_paise, p_participants);

  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', es.user_id, 'share_paise', es.share_paise, 'percent_bps', es.percent_bps) order by es.user_id), '[]'::jsonb)
  into v_old_splits
  from public.expense_splits es where es.expense_id = v_exp.id and es.version = v_exp.version;

  insert into public.expense_revisions (expense_id, group_id, version, change_type, reason, snapshot, changed_by)
  values (v_exp.id, v_exp.group_id, v_exp.version, 'edit', trim(p_reason),
    jsonb_build_object(
      'title', v_exp.title, 'amount_paise', v_exp.amount_paise, 'category_key', v_exp.category_key,
      'spent_at', v_exp.spent_at, 'paid_by', v_exp.paid_by, 'split_mode', v_exp.split_mode,
      'note', v_exp.note, 'splits', v_old_splits),
    v_uid);

  v_new_version := v_exp.version + 1;

  update public.expenses
  set title = trim(p_title), amount_paise = p_amount_paise, category_key = p_category_key,
      spent_at = p_spent_at, paid_by = p_paid_by, split_mode = p_split_mode,
      note = nullif(trim(coalesce(p_note, '')), ''), version = v_new_version, updated_by = v_uid
  where id = v_exp.id;

  insert into public.expense_splits (expense_id, group_id, version, user_id, share_paise, percent_bps)
  select v_exp.id, v_exp.group_id, v_new_version, s.user_id, s.share_paise, s.percent_bps
  from public.compute_splits(p_split_mode, p_amount_paise, p_participants) s;

  perform public.kh_audit(v_exp.group_id, 'expense.edited', 'expenses', v_exp.id::text,
    jsonb_build_object('version', v_new_version, 'reason', trim(p_reason),
      'old_amount_paise', v_exp.amount_paise, 'new_amount_paise', p_amount_paise,
      'old_title', v_exp.title, 'new_title', trim(p_title)));

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  perform public.kh_notify(u.user_id, v_exp.group_id, 'expense_edited',
    jsonb_build_object('title', trim(p_title), 'name', v_name, 'expense_id', v_exp.id), null)
  from (
    select es.user_id from public.expense_splits es
    where es.expense_id = v_exp.id and es.version in (v_exp.version, v_new_version)
    union
    select v_exp.paid_by union select p_paid_by
  ) u
  where u.user_id <> v_uid;

  perform public.kh_check_budgets(v_exp.group_id, p_spent_at);
  return v_new_version;
end;
$$;

create or replace function public.void_expense(
  p_expense_id uuid, p_expected_version integer, p_reason text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_exp public.expenses%rowtype;
  v_role text;
  v_splits jsonb;
  v_name text;
begin
  select * into v_exp from public.expenses e where e.id = p_expense_id for update;
  if not found then
    raise exception 'EXPENSE_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_exp.group_id, 'member');
  perform public.kh_require_active_group(v_exp.group_id);

  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_exp.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_exp.created_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  if v_exp.status <> 'active' then
    raise exception 'EXPENSE_VOIDED';
  end if;
  if p_expected_version is distinct from v_exp.version then
    raise exception 'VERSION_CONFLICT';
  end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 or char_length(p_reason) > 300 then
    raise exception 'REASON_REQUIRED';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', es.user_id, 'share_paise', es.share_paise, 'percent_bps', es.percent_bps) order by es.user_id), '[]'::jsonb)
  into v_splits
  from public.expense_splits es where es.expense_id = v_exp.id and es.version = v_exp.version;

  insert into public.expense_revisions (expense_id, group_id, version, change_type, reason, snapshot, changed_by)
  values (v_exp.id, v_exp.group_id, v_exp.version, 'void', trim(p_reason),
    jsonb_build_object(
      'title', v_exp.title, 'amount_paise', v_exp.amount_paise, 'category_key', v_exp.category_key,
      'spent_at', v_exp.spent_at, 'paid_by', v_exp.paid_by, 'split_mode', v_exp.split_mode,
      'note', v_exp.note, 'splits', v_splits),
    v_uid);

  update public.expenses
  set status = 'voided', void_reason = trim(p_reason), voided_at = now(), voided_by = v_uid, updated_by = v_uid
  where id = v_exp.id;

  perform public.kh_audit(v_exp.group_id, 'expense.voided', 'expenses', v_exp.id::text,
    jsonb_build_object('reason', trim(p_reason), 'amount_paise', v_exp.amount_paise, 'title', v_exp.title));

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  perform public.kh_notify(es.user_id, v_exp.group_id, 'expense_voided',
    jsonb_build_object('title', v_exp.title, 'name', v_name, 'expense_id', v_exp.id), null)
  from public.expense_splits es
  where es.expense_id = v_exp.id and es.version = v_exp.version and es.user_id <> v_uid;
end;
$$;

create or replace function public.add_expense_receipt(
  p_expense_id uuid, p_storage_path text, p_file_name text, p_mime_type text, p_size_bytes integer
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_exp public.expenses%rowtype;
  v_role text;
  v_id uuid;
begin
  select * into v_exp from public.expenses e where e.id = p_expense_id;
  if not found then
    raise exception 'EXPENSE_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_exp.group_id, 'member');
  perform public.kh_require_active_group(v_exp.group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_exp.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_exp.status <> 'active' then
    raise exception 'EXPENSE_VOIDED';
  end if;
  if v_uid not in (v_exp.created_by, v_exp.paid_by) and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  if p_storage_path is null or left(p_storage_path, char_length(v_exp.group_id::text || '/' || v_exp.id::text || '/'))
       <> v_exp.group_id::text || '/' || v_exp.id::text || '/' then
    raise exception 'INVALID_RECEIPT_PATH';
  end if;
  if p_mime_type not in ('image/jpeg', 'image/png', 'image/webp', 'application/pdf') then
    raise exception 'INVALID_FILE_TYPE';
  end if;
  if p_size_bytes is null or p_size_bytes < 1 or p_size_bytes > 5242880 then
    raise exception 'FILE_TOO_LARGE';
  end if;
  if (select count(*) from public.expense_receipts r where r.expense_id = p_expense_id and r.removed_at is null) >= 5 then
    raise exception 'TOO_MANY_RECEIPTS';
  end if;
  perform public.kh_rate_limit('add_receipt', 60, 3600);

  insert into public.expense_receipts (expense_id, group_id, storage_path, file_name, mime_type, size_bytes, uploaded_by)
  values (p_expense_id, v_exp.group_id, p_storage_path, left(p_file_name, 200), p_mime_type, p_size_bytes, v_uid)
  returning id into v_id;

  perform public.kh_audit(v_exp.group_id, 'expense.receipt_added', 'expenses', p_expense_id::text,
    jsonb_build_object('receipt_id', v_id, 'file_name', left(p_file_name, 200)));
  return v_id;
end;
$$;

create or replace function public.remove_expense_receipt(p_receipt_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_r public.expense_receipts%rowtype;
  v_role text;
begin
  select * into v_r from public.expense_receipts r where r.id = p_receipt_id for update;
  if not found then
    raise exception 'RECEIPT_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_r.group_id, 'member');
  perform public.kh_require_active_group(v_r.group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_r.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_r.uploaded_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  update public.expense_receipts set removed_at = coalesce(removed_at, now()), removed_by = v_uid where id = p_receipt_id;
  perform public.kh_audit(v_r.group_id, 'expense.receipt_removed', 'expenses', v_r.expense_id::text,
    jsonb_build_object('receipt_id', p_receipt_id));
end;
$$;

-- ------------------------------------------------------------
-- 7. Budgets
-- ------------------------------------------------------------
-- p_amount_paise = 0 removes the budget. category NULL = overall monthly budget.
create or replace function public.set_group_budget(
  p_group_id uuid, p_category_key text, p_amount_paise bigint
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid;
begin
  v_uid := public.kh_require_role(p_group_id, 'admin');
  perform public.kh_require_active_group(p_group_id);
  if p_category_key is not null and not exists (select 1 from public.expense_categories c where c.key = p_category_key) then
    raise exception 'INVALID_CATEGORY';
  end if;
  if p_amount_paise is null or p_amount_paise < 0 or p_amount_paise > 10000000000 then
    raise exception 'INVALID_AMOUNT';
  end if;

  if p_amount_paise = 0 then
    delete from public.group_budgets gb
    where gb.group_id = p_group_id and coalesce(gb.category_key, '__all__') = coalesce(p_category_key, '__all__');
  else
    insert into public.group_budgets (group_id, category_key, amount_paise, created_by, updated_by)
    values (p_group_id, p_category_key, p_amount_paise, v_uid, v_uid)
    on conflict (group_id, coalesce(category_key, '__all__'))
    do update set amount_paise = excluded.amount_paise, updated_by = v_uid;
  end if;

  perform public.kh_audit(p_group_id, 'budget.set', 'group_budgets', coalesce(p_category_key, 'all'),
    jsonb_build_object('category_key', p_category_key, 'amount_paise', p_amount_paise));
end;
$$;

create or replace function public.list_group_budgets(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'member');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', gb.id, 'category_key', gb.category_key, 'amount_paise', gb.amount_paise
    ) order by gb.category_key nulls first)
    from public.group_budgets gb where gb.group_id = p_group_id
  ), '[]'::jsonb);
end;
$$;

-- ------------------------------------------------------------
-- 8. Read RPCs
-- ------------------------------------------------------------
create or replace function public.list_expense_categories()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'key', c.key, 'name_en', c.name_en, 'name_hi', c.name_hi) order by c.sort_order), '[]'::jsonb)
  from public.expense_categories c
  where (select auth.uid()) is not null;
$$;

create or replace function public.list_expenses(
  p_group_id uuid,
  p_limit integer default 30,
  p_before_ts timestamptz default null,
  p_before_id uuid default null,
  p_search text default null,
  p_category_key text default null,
  p_member_id uuid default null,
  p_from timestamptz default null,
  p_to timestamptz default null,
  p_status text default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_require_role(p_group_id, 'member');
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_rows jsonb;
  v_count integer;
  v_search text := nullif(lower(trim(coalesce(p_search, ''))), '');
begin
  select coalesce(jsonb_agg(t.j order by t.spent_at desc, t.id desc), '[]'::jsonb), count(*)
  into v_rows, v_count
  from (
    select e.id, e.spent_at, jsonb_build_object(
      'id', e.id, 'title', e.title, 'amount_paise', e.amount_paise, 'category_key', e.category_key,
      'spent_at', e.spent_at, 'paid_by', e.paid_by, 'paid_by_name', pp.full_name,
      'split_mode', e.split_mode, 'status', e.status, 'version', e.version, 'note', e.note,
      'created_by', e.created_by, 'created_at', e.created_at,
      'my_share_paise', (select es.share_paise from public.expense_splits es
                         where es.expense_id = e.id and es.version = e.version and es.user_id = v_uid),
      'participant_count', (select count(*) from public.expense_splits es
                            where es.expense_id = e.id and es.version = e.version),
      'receipt_count', (select count(*) from public.expense_receipts r
                        where r.expense_id = e.id and r.removed_at is null)
    ) as j
    from public.expenses e
    join public.profiles pp on pp.id = e.paid_by
    where e.group_id = p_group_id
      and (p_status is null or e.status = p_status)
      and (p_category_key is null or e.category_key = p_category_key)
      and (p_from is null or e.spent_at >= p_from)
      and (p_to is null or e.spent_at < p_to)
      and (v_search is null or position(v_search in lower(e.title)) > 0)
      and (p_member_id is null or e.paid_by = p_member_id or exists (
            select 1 from public.expense_splits es
            where es.expense_id = e.id and es.version = e.version and es.user_id = p_member_id))
      and (p_before_ts is null or p_before_id is null or (e.spent_at, e.id) < (p_before_ts, p_before_id))
    order by e.spent_at desc, e.id desc
    limit v_limit + 1
  ) t;

  if v_count > v_limit then
    v_rows := v_rows - v_limit;  -- drop the sentinel row
    return jsonb_build_object(
      'items', v_rows,
      'next', jsonb_build_object(
        'ts', v_rows -> (v_limit - 1) ->> 'spent_at',
        'id', v_rows -> (v_limit - 1) ->> 'id')
    );
  end if;
  return jsonb_build_object('items', v_rows, 'next', null);
end;
$$;

create or replace function public.get_expense(p_expense_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_exp public.expenses%rowtype;
begin
  select * into v_exp from public.expenses e where e.id = p_expense_id;
  if not found then
    raise exception 'EXPENSE_NOT_FOUND';
  end if;
  perform public.kh_require_role(v_exp.group_id, 'member');

  return jsonb_build_object(
    'expense', jsonb_build_object(
      'id', v_exp.id, 'group_id', v_exp.group_id, 'title', v_exp.title, 'amount_paise', v_exp.amount_paise,
      'category_key', v_exp.category_key, 'spent_at', v_exp.spent_at, 'paid_by', v_exp.paid_by,
      'paid_by_name', (select p.full_name from public.profiles p where p.id = v_exp.paid_by),
      'split_mode', v_exp.split_mode, 'note', v_exp.note, 'status', v_exp.status, 'version', v_exp.version,
      'created_by', v_exp.created_by,
      'created_by_name', (select p.full_name from public.profiles p where p.id = v_exp.created_by),
      'created_at', v_exp.created_at, 'updated_at', v_exp.updated_at,
      'void_reason', v_exp.void_reason, 'voided_at', v_exp.voided_at,
      'voided_by_name', (select p.full_name from public.profiles p where p.id = v_exp.voided_by)
    ),
    'splits', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', es.user_id, 'full_name', p.full_name, 'share_paise', es.share_paise,
        'percent_bps', es.percent_bps) order by es.user_id)
      from public.expense_splits es join public.profiles p on p.id = es.user_id
      where es.expense_id = v_exp.id and es.version = v_exp.version
    ), '[]'::jsonb),
    'receipts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'file_name', r.file_name, 'mime_type', r.mime_type, 'size_bytes', r.size_bytes,
        'storage_path', r.storage_path, 'uploaded_by', r.uploaded_by, 'created_at', r.created_at) order by r.created_at)
      from public.expense_receipts r where r.expense_id = v_exp.id and r.removed_at is null
    ), '[]'::jsonb),
    'revisions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.id, 'version', rv.version, 'change_type', rv.change_type, 'reason', rv.reason,
        'changed_by', rv.changed_by, 'changed_by_name', p.full_name, 'created_at', rv.created_at,
        'snapshot', rv.snapshot) order by rv.id desc)
      from public.expense_revisions rv join public.profiles p on p.id = rv.changed_by
      where rv.expense_id = v_exp.id
    ), '[]'::jsonb)
  );
end;
$$;

-- ------------------------------------------------------------
-- 9. RLS (direct reads stay membership-scoped; no client writes)
-- ------------------------------------------------------------
alter table public.expense_categories enable row level security;
alter table public.expenses enable row level security;
alter table public.expense_splits enable row level security;
alter table public.expense_revisions enable row level security;
alter table public.expense_receipts enable row level security;
alter table public.group_budgets enable row level security;

drop policy if exists expense_categories_read on public.expense_categories;
create policy expense_categories_read on public.expense_categories for select to authenticated using (true);
drop policy if exists expenses_select_members on public.expenses;
create policy expenses_select_members on public.expenses for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists expense_splits_select_members on public.expense_splits;
create policy expense_splits_select_members on public.expense_splits for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists expense_revisions_select_members on public.expense_revisions;
create policy expense_revisions_select_members on public.expense_revisions for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists expense_receipts_select_members on public.expense_receipts;
create policy expense_receipts_select_members on public.expense_receipts for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists group_budgets_select_members on public.group_budgets;
create policy group_budgets_select_members on public.group_budgets for select to authenticated
  using (public.is_group_member(group_id));

revoke all on public.expense_categories, public.expenses, public.expense_splits, public.expense_revisions,
  public.expense_receipts, public.group_budgets from anon, authenticated;
grant select on public.expense_categories, public.expenses, public.expense_splits, public.expense_revisions,
  public.expense_receipts, public.group_budgets to authenticated;

-- ------------------------------------------------------------
-- 10. Function privileges
-- ------------------------------------------------------------
revoke all on function public.kh_user_in_group(uuid, uuid) from public, anon, authenticated;
revoke all on function public.enforce_expense_members() from public, anon, authenticated;
revoke all on function public.enforce_split_member() from public, anon, authenticated;
revoke all on function public.block_hard_delete() from public, anon, authenticated;
revoke all on function public.block_row_update() from public, anon, authenticated;
revoke all on function public.guard_expense_update() from public, anon, authenticated;
revoke all on function public.check_expense_split_sum() from public, anon, authenticated;
revoke all on function public.kh_check_budgets(uuid, timestamptz) from public, anon, authenticated;
revoke all on function public.kh_validate_expense_input(uuid, uuid, text, bigint, text, timestamptz, uuid, jsonb, text)
  from public, anon, authenticated;

revoke all on function public.compute_splits(text, bigint, jsonb) from public, anon;
revoke all on function public.create_expense(uuid, uuid, text, bigint, text, timestamptz, uuid, text, jsonb, text) from public, anon;
revoke all on function public.edit_expense(uuid, integer, text, text, bigint, text, timestamptz, uuid, text, jsonb, text) from public, anon;
revoke all on function public.void_expense(uuid, integer, text) from public, anon;
revoke all on function public.add_expense_receipt(uuid, text, text, text, integer) from public, anon;
revoke all on function public.remove_expense_receipt(uuid) from public, anon;
revoke all on function public.set_group_budget(uuid, text, bigint) from public, anon;
revoke all on function public.list_group_budgets(uuid) from public, anon;
revoke all on function public.list_expense_categories() from public, anon;
revoke all on function public.list_expenses(uuid, integer, timestamptz, uuid, text, text, uuid, timestamptz, timestamptz, text) from public, anon;
revoke all on function public.get_expense(uuid) from public, anon;

grant execute on function public.compute_splits(text, bigint, jsonb) to authenticated;
grant execute on function public.create_expense(uuid, uuid, text, bigint, text, timestamptz, uuid, text, jsonb, text) to authenticated;
grant execute on function public.edit_expense(uuid, integer, text, text, bigint, text, timestamptz, uuid, text, jsonb, text) to authenticated;
grant execute on function public.void_expense(uuid, integer, text) to authenticated;
grant execute on function public.add_expense_receipt(uuid, text, text, text, integer) to authenticated;
grant execute on function public.remove_expense_receipt(uuid) to authenticated;
grant execute on function public.set_group_budget(uuid, text, bigint) to authenticated;
grant execute on function public.list_group_budgets(uuid) to authenticated;
grant execute on function public.list_expense_categories() to authenticated;
grant execute on function public.list_expenses(uuid, integer, timestamptz, uuid, text, text, uuid, timestamptz, timestamptz, text) to authenticated;
grant execute on function public.get_expense(uuid) to authenticated;

commit;


-- ============================================================
-- 0004_payments_ledger.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0004 PAYMENTS, LEDGER, BALANCES, REPORTS, REMINDERS
--
-- Balance formula (per member, confirmed records only):
--   net = paid_for_group - allocated_share + settlements_paid_out - settlements_received
-- Positive net  => the member should RECEIVE money ("You will get").
-- Negative net  => the member OWES money ("You need to pay").
--
-- NOTE: the original build pack wrote the settlement terms with the opposite
-- signs ("- settlement paid + settlement received"). That would make a debtor
-- who pays back appear to owe MORE, so the economically correct signs are
-- used here and covered by tests (a full settlement brings the net to 0).
-- ============================================================

begin;

create table if not exists public.payments (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete restrict,
  from_user uuid not null references public.profiles(id),
  to_user uuid not null references public.profiles(id),
  amount_paise bigint not null check (amount_paise > 0 and amount_paise <= 10000000000),
  method text not null check (method in ('cash', 'upi', 'bank', 'other')),
  paid_at timestamptz not null,
  reference text check (reference is null or char_length(reference) <= 100),
  note text check (note is null or char_length(note) <= 300),
  status text not null default 'pending'
    check (status in ('pending', 'confirmed', 'rejected', 'cancelled', 'reversed')),
  created_by uuid not null references public.profiles(id),
  idempotency_key uuid not null,
  decided_by uuid references public.profiles(id),
  decided_at timestamptz,
  decision_note text check (decision_note is null or char_length(decision_note) <= 300),
  reversed_by uuid references public.profiles(id),
  reversed_at timestamptz,
  reverse_reason text check (reverse_reason is null or char_length(reverse_reason) <= 300),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (from_user <> to_user),
  check ((status = 'pending') = (decided_at is null)),
  check ((status = 'reversed') = (reversed_at is not null)),
  unique (id, group_id),
  unique (group_id, created_by, idempotency_key)
);
create index if not exists idx_payments_group_paid on public.payments(group_id, paid_at desc, id desc);
create index if not exists idx_payments_group_from on public.payments(group_id, from_user);
create index if not exists idx_payments_group_to on public.payments(group_id, to_user);
create index if not exists idx_payments_group_status on public.payments(group_id, status);

create or replace function public.enforce_payment_members()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not public.kh_user_in_group(new.group_id, new.from_user)
     or not public.kh_user_in_group(new.group_id, new.to_user)
     or not public.kh_user_in_group(new.group_id, new.created_by) then
    raise exception 'PAYMENT_PARTY_NOT_MEMBER';
  end if;
  return new;
end;
$$;

create or replace function public.guard_payment_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (new.group_id, new.from_user, new.to_user, new.amount_paise, new.method, new.paid_at,
      new.created_by, new.idempotency_key, new.created_at)
     is distinct from
     (old.group_id, old.from_user, old.to_user, old.amount_paise, old.method, old.paid_at,
      old.created_by, old.idempotency_key, old.created_at) then
    raise exception 'IMMUTABLE_RECORD';
  end if;
  if new.status is distinct from old.status then
    if not (
      (old.status = 'pending' and new.status in ('confirmed', 'rejected', 'cancelled'))
      or (old.status = 'confirmed' and new.status = 'reversed')
    ) then
      raise exception 'INVALID_PAYMENT_TRANSITION';
    end if;
  end if;
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists trg_payments_members on public.payments;
create trigger trg_payments_members before insert on public.payments
  for each row execute function public.enforce_payment_members();
drop trigger if exists trg_payments_guard on public.payments;
create trigger trg_payments_guard before update on public.payments
  for each row execute function public.guard_payment_update();
drop trigger if exists trg_payments_no_delete on public.payments;
create trigger trg_payments_no_delete before delete on public.payments
  for each row execute function public.block_hard_delete();

alter table public.payments enable row level security;
drop policy if exists payments_select_members on public.payments;
create policy payments_select_members on public.payments for select to authenticated
  using (public.is_group_member(group_id));
revoke all on public.payments from anon, authenticated;
grant select on public.payments to authenticated;

-- ------------------------------------------------------------
-- Write RPCs
-- ------------------------------------------------------------
-- Who confirms?  Only the RECEIVER confirms a payment (or an admin when the
-- receiver has left the group). A payment recorded by the receiver is
-- confirmed immediately because the receiver is acknowledging it themselves.
-- Recording is a manual bookkeeping action - it is NOT proof of a bank/UPI transfer.
create or replace function public.record_payment(
  p_group_id uuid,
  p_idempotency_key uuid,
  p_from_user uuid,
  p_to_user uuid,
  p_amount_paise bigint,
  p_method text,
  p_paid_at timestamptz,
  p_reference text default null,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_role text;
  v_id uuid;
  v_status text;
  v_name text;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  if p_idempotency_key is null then
    raise exception 'IDEMPOTENCY_KEY_REQUIRED';
  end if;

  select pm.id into v_id from public.payments pm
  where pm.group_id = p_group_id and pm.created_by = v_uid and pm.idempotency_key = p_idempotency_key;
  if v_id is not null then
    return v_id;
  end if;

  perform public.kh_rate_limit('record_payment', 120, 3600);

  select gm.role into v_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';

  if p_from_user is null or p_to_user is null or p_from_user = p_to_user then
    raise exception 'INVALID_PAYMENT_PARTIES';
  end if;
  if v_uid not in (p_from_user, p_to_user) and v_role not in ('owner', 'admin') then
    raise exception 'PAYMENT_ACTION_NOT_ALLOWED' using errcode = '42501';
  end if;
  if not public.kh_user_in_group(p_group_id, p_from_user) or not public.kh_user_in_group(p_group_id, p_to_user) then
    raise exception 'PAYMENT_PARTY_NOT_MEMBER';
  end if;
  if p_amount_paise is null or p_amount_paise <= 0 or p_amount_paise > 10000000000 then
    raise exception 'INVALID_AMOUNT';
  end if;
  if p_method is null or p_method not in ('cash', 'upi', 'bank', 'other') then
    raise exception 'INVALID_METHOD';
  end if;
  if p_paid_at is null or p_paid_at > now() + interval '1 day' or p_paid_at < now() - interval '10 years' then
    raise exception 'INVALID_DATE';
  end if;
  if p_reference is not null and char_length(p_reference) > 100 then
    raise exception 'REFERENCE_TOO_LONG';
  end if;
  if p_note is not null and char_length(p_note) > 300 then
    raise exception 'NOTE_TOO_LONG';
  end if;

  v_status := case when v_uid = p_to_user then 'confirmed' else 'pending' end;

  insert into public.payments (
    group_id, from_user, to_user, amount_paise, method, paid_at, reference, note,
    status, created_by, idempotency_key, decided_by, decided_at
  )
  values (
    p_group_id, p_from_user, p_to_user, p_amount_paise, p_method, p_paid_at,
    nullif(trim(coalesce(p_reference, '')), ''), nullif(trim(coalesce(p_note, '')), ''),
    v_status, v_uid, p_idempotency_key,
    case when v_status = 'confirmed' then v_uid end,
    case when v_status = 'confirmed' then now() end
  )
  on conflict (group_id, created_by, idempotency_key) do nothing
  returning id into v_id;

  if v_id is null then
    select pm.id into v_id from public.payments pm
    where pm.group_id = p_group_id and pm.created_by = v_uid and pm.idempotency_key = p_idempotency_key;
    return v_id;
  end if;

  perform public.kh_audit(p_group_id, 'payment.recorded', 'payments', v_id::text,
    jsonb_build_object('from', p_from_user, 'to', p_to_user, 'amount_paise', p_amount_paise,
                       'method', p_method, 'status', v_status));

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  if v_status = 'pending' then
    perform public.kh_notify(p_to_user, p_group_id, 'payment_pending',
      jsonb_build_object('name', v_name, 'amount_paise', p_amount_paise, 'payment_id', v_id), null);
  end if;
  if p_from_user <> v_uid then
    perform public.kh_notify(p_from_user, p_group_id, 'payment_recorded',
      jsonb_build_object('name', v_name, 'amount_paise', p_amount_paise, 'payment_id', v_id,
                         'status', v_status), null);
  end if;
  return v_id;
end;
$$;

-- p_action: 'confirm' | 'reject' | 'cancel' | 'reverse'
create or replace function public.update_payment_status(
  p_payment_id uuid, p_action text, p_note text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_pm public.payments%rowtype;
  v_role text;
  v_receiver_active boolean;
  v_is_receiver boolean;
  v_can_decide boolean;
  v_name text;
  v_other uuid;
  v_type text;
begin
  if p_action is null or p_action not in ('confirm', 'reject', 'cancel', 'reverse') then
    raise exception 'INVALID_ACTION';
  end if;

  select * into v_pm from public.payments pm where pm.id = p_payment_id for update;
  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  v_uid := public.kh_require_role(v_pm.group_id, 'member');
  perform public.kh_require_active_group(v_pm.group_id);

  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_pm.group_id and gm.user_id = v_uid and gm.status = 'active';
  v_receiver_active := exists (
    select 1 from public.group_members gm
    where gm.group_id = v_pm.group_id and gm.user_id = v_pm.to_user and gm.status = 'active');
  v_is_receiver := (v_uid = v_pm.to_user);
  v_can_decide := v_is_receiver or (v_role in ('owner', 'admin') and not v_receiver_active);

  if p_action = 'confirm' then
    if v_pm.status <> 'pending' then raise exception 'PAYMENT_NOT_PENDING'; end if;
    if not v_can_decide then raise exception 'PAYMENT_ACTION_NOT_ALLOWED' using errcode = '42501'; end if;
    update public.payments set status = 'confirmed', decided_by = v_uid, decided_at = now(),
      decision_note = nullif(trim(coalesce(p_note, '')), '') where id = v_pm.id;
    v_type := 'payment_confirmed';

  elsif p_action = 'reject' then
    if v_pm.status <> 'pending' then raise exception 'PAYMENT_NOT_PENDING'; end if;
    if not v_can_decide then raise exception 'PAYMENT_ACTION_NOT_ALLOWED' using errcode = '42501'; end if;
    if p_note is null or char_length(trim(p_note)) < 3 then raise exception 'REASON_REQUIRED'; end if;
    update public.payments set status = 'rejected', decided_by = v_uid, decided_at = now(),
      decision_note = left(trim(p_note), 300) where id = v_pm.id;
    v_type := 'payment_rejected';

  elsif p_action = 'cancel' then
    if v_pm.status <> 'pending' then raise exception 'PAYMENT_NOT_PENDING'; end if;
    if v_uid not in (v_pm.created_by, v_pm.from_user) then
      raise exception 'PAYMENT_ACTION_NOT_ALLOWED' using errcode = '42501';
    end if;
    update public.payments set status = 'cancelled', decided_by = v_uid, decided_at = now(),
      decision_note = nullif(left(trim(coalesce(p_note, '')), 300), '') where id = v_pm.id;
    v_type := 'payment_cancelled';

  else -- reverse
    if v_pm.status <> 'confirmed' then raise exception 'PAYMENT_NOT_CONFIRMED'; end if;
    if not (v_is_receiver or v_role in ('owner', 'admin')) then
      raise exception 'PAYMENT_ACTION_NOT_ALLOWED' using errcode = '42501';
    end if;
    if p_note is null or char_length(trim(p_note)) < 3 then raise exception 'REASON_REQUIRED'; end if;
    update public.payments set status = 'reversed', reversed_by = v_uid, reversed_at = now(),
      reverse_reason = left(trim(p_note), 300) where id = v_pm.id;
    v_type := 'payment_reversed';
  end if;

  perform public.kh_audit(v_pm.group_id, 'payment.' || p_action, 'payments', v_pm.id::text,
    jsonb_build_object('amount_paise', v_pm.amount_paise, 'from', v_pm.from_user, 'to', v_pm.to_user,
                       'note', nullif(left(trim(coalesce(p_note, '')), 300), '')));

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  for v_other in
    select u from (values (v_pm.from_user), (v_pm.to_user), (v_pm.created_by)) t(u) group by u
  loop
    if v_other <> v_uid then
      perform public.kh_notify(v_other, v_pm.group_id, v_type,
        jsonb_build_object('name', v_name, 'amount_paise', v_pm.amount_paise, 'payment_id', v_pm.id), null);
    end if;
  end loop;
end;
$$;

-- Friendly nudge (in-app notification). Max one per target per 12 hours.
create or replace function public.send_payment_reminder(p_group_id uuid, p_to_user uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_net bigint;
  v_name text;
  v_group_name text;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  if p_to_user = v_uid then
    raise exception 'INVALID_PAYMENT_PARTIES';
  end if;
  if not exists (select 1 from public.group_members gm
                 where gm.group_id = p_group_id and gm.user_id = p_to_user and gm.status = 'active') then
    raise exception 'PAYMENT_PARTY_NOT_MEMBER';
  end if;

  select coalesce((
    select (b ->> 'net_paise')::bigint
    from jsonb_array_elements(public.get_group_balances(p_group_id, null, null)) b
    where (b ->> 'user_id')::uuid = p_to_user
  ), 0) into v_net;
  if v_net >= 0 then
    raise exception 'NOTHING_TO_REMIND';
  end if;

  perform public.kh_rate_limit('remind:' || p_to_user::text, 1, 43200);

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  select g.name into v_group_name from public.groups g where g.id = p_group_id;
  perform public.kh_notify(p_to_user, p_group_id, 'payment_reminder',
    jsonb_build_object('name', v_name, 'owed_paise', -v_net, 'group_name', v_group_name), null);
end;
$$;

-- ------------------------------------------------------------
-- Balances & ledger
-- ------------------------------------------------------------
create or replace function public.get_group_balances(
  p_group_id uuid, p_from timestamptz default null, p_to timestamptz default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'member');
  return coalesce((
    with members as (
      select distinct on (gm.user_id) gm.user_id, gm.status
      from public.group_members gm
      where gm.group_id = p_group_id
      order by gm.user_id, (gm.status = 'active') desc, gm.joined_at desc
    ),
    exp as (
      select e.id, e.version, e.paid_by, e.amount_paise
      from public.expenses e
      where e.group_id = p_group_id and e.status = 'active'
        and (p_from is null or e.spent_at >= p_from) and (p_to is null or e.spent_at < p_to)
    ),
    paid as (select x.paid_by as uid, sum(x.amount_paise) as s from exp x group by x.paid_by),
    shares as (
      select es.user_id as uid, sum(es.share_paise) as s
      from public.expense_splits es join exp x on x.id = es.expense_id and x.version = es.version
      group by es.user_id
    ),
    pay as (
      select pm.from_user, pm.to_user, pm.amount_paise
      from public.payments pm
      where pm.group_id = p_group_id and pm.status = 'confirmed'
        and (p_from is null or pm.paid_at >= p_from) and (p_to is null or pm.paid_at < p_to)
    ),
    pout as (select from_user as uid, sum(amount_paise) as s from pay group by from_user),
    pin as (select to_user as uid, sum(amount_paise) as s from pay group by to_user),
    rows as (
      select m.user_id, m.status,
             coalesce(pd.s, 0) as paid_paise,
             coalesce(sh.s, 0) as share_paise,
             coalesce(po.s, 0) as settlement_paid_paise,
             coalesce(pi.s, 0) as settlement_received_paise
      from members m
      left join paid pd on pd.uid = m.user_id
      left join shares sh on sh.uid = m.user_id
      left join pout po on po.uid = m.user_id
      left join pin pi on pi.uid = m.user_id
    )
    select jsonb_agg(jsonb_build_object(
      'user_id', r.user_id, 'full_name', p.full_name, 'is_deleted', p.deleted_at is not null,
      'status', r.status,
      'paid_paise', r.paid_paise, 'share_paise', r.share_paise,
      'settlement_paid_paise', r.settlement_paid_paise,
      'settlement_received_paise', r.settlement_received_paise,
      'net_paise', r.paid_paise - r.share_paise + r.settlement_paid_paise - r.settlement_received_paise
    ) order by (r.status = 'active') desc, lower(p.full_name))
    from rows r join public.profiles p on p.id = r.user_id
    where r.status = 'active'
       or r.paid_paise <> 0 or r.share_paise <> 0 or r.settlement_paid_paise <> 0 or r.settlement_received_paise <> 0
  ), '[]'::jsonb);
end;
$$;

create or replace function public.get_member_ledger(
  p_group_id uuid, p_user_id uuid, p_limit integer default 50, p_offset integer default 0,
  p_from timestamptz default null, p_to timestamptz default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_summary jsonb;
  v_entries jsonb;
  v_total bigint;
begin
  perform public.kh_require_role(p_group_id, 'member');
  if not public.kh_user_in_group(p_group_id, p_user_id) then
    raise exception 'NOT_A_MEMBER' using errcode = '42501';
  end if;

  select b into v_summary
  from jsonb_array_elements(public.get_group_balances(p_group_id, p_from, p_to)) b
  where (b ->> 'user_id')::uuid = p_user_id;
  if v_summary is null then
    v_summary := jsonb_build_object('user_id', p_user_id, 'paid_paise', 0, 'share_paise', 0,
      'settlement_paid_paise', 0, 'settlement_received_paise', 0, 'net_paise', 0);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'kind', t.kind, 'id', t.ref_id, 'title', t.title, 'occurred_at', t.occurred_at,
    'paid_paise', t.paid_paise, 'share_paise', t.share_paise, 'effect_paise', t.effect_paise,
    'status', t.status, 'counterparty_id', t.counterparty_id, 'counterparty_name', t.counterparty_name,
    'category_key', t.category_key
  ) order by t.occurred_at desc, t.ref_id desc), '[]'::jsonb), coalesce(max(t.total), 0)
  into v_entries, v_total
  from (
    select u.*, count(*) over () as total
    from (
      select 'expense'::text as kind, e.id as ref_id, e.title as title, e.spent_at as occurred_at,
             case when e.paid_by = p_user_id then e.amount_paise else 0 end as paid_paise,
             coalesce(es.share_paise, 0) as share_paise,
             (case when e.paid_by = p_user_id then e.amount_paise else 0 end - coalesce(es.share_paise, 0)) as effect_paise,
             'active'::text as status, null::uuid as counterparty_id, null::text as counterparty_name,
             e.category_key as category_key
      from public.expenses e
      left join public.expense_splits es
        on es.expense_id = e.id and es.version = e.version and es.user_id = p_user_id
      where e.group_id = p_group_id and e.status = 'active'
        and (e.paid_by = p_user_id or es.user_id is not null)
        and (p_from is null or e.spent_at >= p_from) and (p_to is null or e.spent_at < p_to)
      union all
      select case when pm.from_user = p_user_id then 'payment_out' else 'payment_in' end,
             pm.id, coalesce(pm.reference, pm.method), pm.paid_at,
             0::bigint, 0::bigint,
             case when pm.status <> 'confirmed' then 0::bigint
                  when pm.from_user = p_user_id then pm.amount_paise
                  else -pm.amount_paise end,
             pm.status,
             case when pm.from_user = p_user_id then pm.to_user else pm.from_user end,
             (select pp.full_name from public.profiles pp
              where pp.id = case when pm.from_user = p_user_id then pm.to_user else pm.from_user end),
             null::text
      from public.payments pm
      where pm.group_id = p_group_id and (pm.from_user = p_user_id or pm.to_user = p_user_id)
        and (p_from is null or pm.paid_at >= p_from) and (p_to is null or pm.paid_at < p_to)
    ) u
    order by u.occurred_at desc, u.ref_id desc
    limit v_limit offset v_offset
  ) t;

  return jsonb_build_object(
    'summary', v_summary, 'entries', v_entries, 'total', v_total,
    'has_more', (v_offset + v_limit) < v_total
  );
end;
$$;

create or replace function public.list_payments(
  p_group_id uuid,
  p_limit integer default 30,
  p_before_ts timestamptz default null,
  p_before_id uuid default null,
  p_status text default null,
  p_member_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
  v_rows jsonb;
  v_count integer;
begin
  perform public.kh_require_role(p_group_id, 'member');
  select coalesce(jsonb_agg(t.j order by t.paid_at desc, t.id desc), '[]'::jsonb), count(*)
  into v_rows, v_count
  from (
    select pm.id, pm.paid_at, jsonb_build_object(
      'id', pm.id, 'from_user', pm.from_user, 'from_name', pf.full_name,
      'to_user', pm.to_user, 'to_name', pt.full_name,
      'amount_paise', pm.amount_paise, 'method', pm.method, 'paid_at', pm.paid_at,
      'reference', pm.reference, 'note', pm.note, 'status', pm.status,
      'created_by', pm.created_by, 'decided_by', pm.decided_by, 'decided_at', pm.decided_at,
      'decision_note', pm.decision_note, 'reverse_reason', pm.reverse_reason, 'created_at', pm.created_at,
      'receiver_active', exists (select 1 from public.group_members gm
                                 where gm.group_id = pm.group_id and gm.user_id = pm.to_user and gm.status = 'active')
    ) as j
    from public.payments pm
    join public.profiles pf on pf.id = pm.from_user
    join public.profiles pt on pt.id = pm.to_user
    where pm.group_id = p_group_id
      and (p_status is null or pm.status = p_status)
      and (p_member_id is null or pm.from_user = p_member_id or pm.to_user = p_member_id)
      and (p_before_ts is null or p_before_id is null or (pm.paid_at, pm.id) < (p_before_ts, p_before_id))
    order by pm.paid_at desc, pm.id desc
    limit v_limit + 1
  ) t;

  if v_count > v_limit then
    v_rows := v_rows - v_limit;
    return jsonb_build_object('items', v_rows, 'next', jsonb_build_object(
      'ts', v_rows -> (v_limit - 1) ->> 'paid_at', 'id', v_rows -> (v_limit - 1) ->> 'id'));
  end if;
  return jsonb_build_object('items', v_rows, 'next', null);
end;
$$;

-- ------------------------------------------------------------
-- Monthly report (month boundaries follow the GROUP timezone)
-- ------------------------------------------------------------
create or replace function public.get_group_report(p_group_id uuid, p_month date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_tz text;
  v_local_month timestamp;
  v_start timestamptz;
  v_end timestamptz;
  v_total bigint;
  v_count bigint;
  v_by_cat jsonb;
  v_by_member jsonb;
  v_monthly jsonb;
  v_budgets jsonb;
begin
  perform public.kh_require_role(p_group_id, 'member');
  if p_month is null then
    raise exception 'INVALID_DATE';
  end if;
  select g.timezone into v_tz from public.groups g where g.id = p_group_id;
  v_local_month := date_trunc('month', p_month::timestamp);
  v_start := v_local_month at time zone v_tz;
  v_end := (v_local_month + interval '1 month') at time zone v_tz;

  select coalesce(sum(e.amount_paise), 0), count(*) into v_total, v_count
  from public.expenses e
  where e.group_id = p_group_id and e.status = 'active' and e.spent_at >= v_start and e.spent_at < v_end;

  select coalesce(jsonb_agg(jsonb_build_object(
    'category_key', c.category_key, 'total_paise', c.total, 'count', c.cnt) order by c.total desc), '[]'::jsonb)
  into v_by_cat
  from (
    select e.category_key, sum(e.amount_paise) as total, count(*) as cnt
    from public.expenses e
    where e.group_id = p_group_id and e.status = 'active' and e.spent_at >= v_start and e.spent_at < v_end
    group by e.category_key
  ) c;

  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', b ->> 'user_id', 'full_name', b ->> 'full_name', 'status', b ->> 'status',
    'paid_paise', (b ->> 'paid_paise')::bigint, 'share_paise', (b ->> 'share_paise')::bigint,
    'net_paise', (b ->> 'net_paise')::bigint)), '[]'::jsonb)
  into v_by_member
  from jsonb_array_elements(public.get_group_balances(p_group_id, v_start, v_end)) b;

  select coalesce(jsonb_agg(jsonb_build_object('month', m.label, 'total_paise', m.total) order by m.label), '[]'::jsonb)
  into v_monthly
  from (
    select to_char(ms.m_local, 'YYYY-MM') as label,
           coalesce((
             select sum(e.amount_paise) from public.expenses e
             where e.group_id = p_group_id and e.status = 'active'
               and e.spent_at >= (ms.m_local at time zone v_tz)
               and e.spent_at < ((ms.m_local + interval '1 month') at time zone v_tz)
           ), 0) as total
    from (select v_local_month - (n || ' month')::interval as m_local from generate_series(0, 5) n) ms
  ) m;

  select coalesce(jsonb_agg(jsonb_build_object(
    'category_key', gb.category_key, 'amount_paise', gb.amount_paise,
    'spent_paise', case when gb.category_key is null then v_total else coalesce((
        select sum(e.amount_paise) from public.expenses e
        where e.group_id = p_group_id and e.status = 'active' and e.category_key = gb.category_key
          and e.spent_at >= v_start and e.spent_at < v_end), 0) end
  ) order by gb.category_key nulls first), '[]'::jsonb)
  into v_budgets
  from public.group_budgets gb where gb.group_id = p_group_id;

  return jsonb_build_object(
    'month', to_char(v_local_month, 'YYYY-MM'), 'from', v_start, 'to', v_end, 'timezone', v_tz,
    'total_paise', v_total, 'expense_count', v_count,
    'by_category', v_by_cat, 'by_member', v_by_member, 'monthly_totals', v_monthly, 'budgets', v_budgets
  );
end;
$$;

