-- ============================================================
-- 0005_utilities.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0005 DAILY UTILITIES: shared shopping list + notices
-- ============================================================

begin;

create table if not exists public.shopping_lists (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  name text not null check (char_length(trim(name)) between 1 and 80),
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  archived_at timestamptz,
  unique (id, group_id)
);
create index if not exists idx_shopping_lists_group on public.shopping_lists(group_id);

create table if not exists public.shopping_list_items (
  id uuid primary key default gen_random_uuid(),
  list_id uuid not null,
  group_id uuid not null,
  name text not null check (char_length(trim(name)) between 1 and 120),
  quantity text check (quantity is null or char_length(quantity) <= 40),
  status text not null default 'needed' check (status in ('needed', 'bought')),
  added_by uuid not null references public.profiles(id),
  bought_by uuid references public.profiles(id),
  bought_at timestamptz,
  removed_at timestamptz,
  created_at timestamptz not null default now(),
  foreign key (list_id, group_id) references public.shopping_lists(id, group_id) on delete cascade,
  check ((status = 'bought') = (bought_at is not null))
);
create index if not exists idx_shopping_items_list on public.shopping_list_items(list_id, status) where removed_at is null;
create index if not exists idx_shopping_items_group on public.shopping_list_items(group_id);

create table if not exists public.group_notices (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  title text not null check (char_length(trim(title)) between 1 and 120),
  body text not null check (char_length(body) <= 2000),
  pinned boolean not null default false,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by uuid references public.profiles(id)
);
create index if not exists idx_group_notices_group on public.group_notices(group_id, pinned desc, created_at desc)
  where deleted_at is null;

drop trigger if exists trg_notices_updated_at on public.group_notices;
create trigger trg_notices_updated_at before update on public.group_notices
  for each row execute function public.set_updated_at();

alter table public.shopping_lists enable row level security;
alter table public.shopping_list_items enable row level security;
alter table public.group_notices enable row level security;

drop policy if exists shopping_lists_select on public.shopping_lists;
create policy shopping_lists_select on public.shopping_lists for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists shopping_items_select on public.shopping_list_items;
create policy shopping_items_select on public.shopping_list_items for select to authenticated
  using (public.is_group_member(group_id));
drop policy if exists group_notices_select on public.group_notices;
create policy group_notices_select on public.group_notices for select to authenticated
  using (public.is_group_member(group_id));

revoke all on public.shopping_lists, public.shopping_list_items, public.group_notices from anon, authenticated;
grant select on public.shopping_lists, public.shopping_list_items, public.group_notices to authenticated;

-- ---------------- Shopping list ----------------
create or replace function public.get_shopping_list(p_group_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_list_id uuid;
  v_list_name text;
  v_uid uuid;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');

  select sl.id, sl.name into v_list_id, v_list_name
  from public.shopping_lists sl
  where sl.group_id = p_group_id and sl.archived_at is null
  order by sl.created_at limit 1;

  if v_list_id is null and exists (select 1 from public.groups g where g.id = p_group_id and g.status = 'active') then
    insert into public.shopping_lists (group_id, name, created_by)
    values (p_group_id, 'Shopping list', v_uid)
    returning id, name into v_list_id, v_list_name;
  end if;

  return jsonb_build_object(
    'list_id', v_list_id,
    'name', v_list_name,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'name', i.name, 'quantity', i.quantity, 'status', i.status,
        'added_by', i.added_by, 'added_by_name', pa.full_name,
        'bought_by', i.bought_by, 'bought_by_name', pb.full_name,
        'bought_at', i.bought_at, 'created_at', i.created_at
      ) order by (i.status = 'bought'), case when i.status = 'needed' then i.created_at end desc, i.bought_at desc)
      from (
        select * from public.shopping_list_items si
        where si.list_id = v_list_id and si.removed_at is null
        order by (si.status = 'bought'), si.created_at desc
        limit 300
      ) i
      join public.profiles pa on pa.id = i.added_by
      left join public.profiles pb on pb.id = i.bought_by
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.add_shopping_item(p_group_id uuid, p_name text, p_quantity text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_list_id uuid;
  v_id uuid;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  if p_name is null or char_length(trim(p_name)) not between 1 and 120 then
    raise exception 'INVALID_TITLE';
  end if;
  if p_quantity is not null and char_length(p_quantity) > 40 then
    raise exception 'INVALID_QUANTITY';
  end if;
  perform public.kh_rate_limit('shopping_add', 200, 3600);

  select sl.id into v_list_id from public.shopping_lists sl
  where sl.group_id = p_group_id and sl.archived_at is null order by sl.created_at limit 1;
  if v_list_id is null then
    insert into public.shopping_lists (group_id, name, created_by)
    values (p_group_id, 'Shopping list', v_uid) returning id into v_list_id;
  end if;

  if (select count(*) from public.shopping_list_items si
      where si.list_id = v_list_id and si.removed_at is null and si.status = 'needed') >= 300 then
    raise exception 'LIST_FULL';
  end if;

  insert into public.shopping_list_items (list_id, group_id, name, quantity, added_by)
  values (v_list_id, p_group_id, trim(p_name), nullif(trim(coalesce(p_quantity, '')), ''), v_uid)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.set_shopping_item_status(p_item_id uuid, p_bought boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_group uuid;
begin
  select si.group_id into v_group from public.shopping_list_items si where si.id = p_item_id and si.removed_at is null;
  if v_group is null then
    raise exception 'ITEM_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_group, 'member');
  perform public.kh_require_active_group(v_group);
  update public.shopping_list_items
  set status = case when p_bought then 'bought' else 'needed' end,
      bought_by = case when p_bought then v_uid end,
      bought_at = case when p_bought then now() end
  where id = p_item_id;
end;
$$;

create or replace function public.remove_shopping_item(p_item_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_item public.shopping_list_items%rowtype;
  v_role text;
begin
  select * into v_item from public.shopping_list_items si where si.id = p_item_id and si.removed_at is null;
  if not found then
    raise exception 'ITEM_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_item.group_id, 'member');
  perform public.kh_require_active_group(v_item.group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_item.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_item.added_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  update public.shopping_list_items set removed_at = now() where id = p_item_id;
end;
$$;

create or replace function public.clear_bought_items(p_group_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare v_count integer;
begin
  perform public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  update public.shopping_list_items set removed_at = now()
  where group_id = p_group_id and status = 'bought' and removed_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ---------------- Notices ----------------
create or replace function public.list_notices(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'member');
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', n.id, 'title', n.title, 'body', n.body, 'pinned', n.pinned,
      'created_by', n.created_by, 'created_by_name', p.full_name,
      'created_at', n.created_at, 'updated_at', n.updated_at
    ) order by n.pinned desc, n.created_at desc)
    from (
      select * from public.group_notices gn
      where gn.group_id = p_group_id and gn.deleted_at is null
      order by gn.pinned desc, gn.created_at desc
      limit 100
    ) n
    join public.profiles p on p.id = n.created_by
  ), '[]'::jsonb);
end;
$$;

create or replace function public.create_notice(
  p_group_id uuid, p_title text, p_body text, p_pinned boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_role text;
  v_id uuid;
  v_name text;
begin
  v_uid := public.kh_require_role(p_group_id, 'member');
  perform public.kh_require_active_group(p_group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';
  if p_title is null or char_length(trim(p_title)) not between 1 and 120 then
    raise exception 'INVALID_TITLE';
  end if;
  if p_body is null or char_length(p_body) > 2000 then
    raise exception 'NOTE_TOO_LONG';
  end if;
  if coalesce(p_pinned, false) and v_role not in ('owner', 'admin') then
    raise exception 'ADMIN_REQUIRED' using errcode = '42501';
  end if;
  perform public.kh_rate_limit('create_notice', 30, 3600);

  insert into public.group_notices (group_id, title, body, pinned, created_by)
  values (p_group_id, trim(p_title), p_body, coalesce(p_pinned, false), v_uid)
  returning id into v_id;

  select p.full_name into v_name from public.profiles p where p.id = v_uid;
  perform public.kh_notify(gm.user_id, p_group_id, 'notice_posted',
    jsonb_build_object('title', trim(p_title), 'name', v_name, 'notice_id', v_id), null)
  from public.group_members gm
  where gm.group_id = p_group_id and gm.status = 'active' and gm.user_id <> v_uid;
  return v_id;
end;
$$;

create or replace function public.update_notice(
  p_notice_id uuid, p_title text, p_body text, p_pinned boolean default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_n public.group_notices%rowtype;
  v_role text;
begin
  select * into v_n from public.group_notices gn where gn.id = p_notice_id and gn.deleted_at is null for update;
  if not found then
    raise exception 'NOTICE_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_n.group_id, 'member');
  perform public.kh_require_active_group(v_n.group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_n.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_n.created_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  if p_pinned is not null and p_pinned <> v_n.pinned and v_role not in ('owner', 'admin') then
    raise exception 'ADMIN_REQUIRED' using errcode = '42501';
  end if;
  if p_title is null or char_length(trim(p_title)) not between 1 and 120 then
    raise exception 'INVALID_TITLE';
  end if;
  if p_body is null or char_length(p_body) > 2000 then
    raise exception 'NOTE_TOO_LONG';
  end if;
  update public.group_notices
  set title = trim(p_title), body = p_body, pinned = coalesce(p_pinned, pinned)
  where id = p_notice_id;
end;
$$;

create or replace function public.delete_notice(p_notice_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid;
  v_n public.group_notices%rowtype;
  v_role text;
begin
  select * into v_n from public.group_notices gn where gn.id = p_notice_id and gn.deleted_at is null for update;
  if not found then
    raise exception 'NOTICE_NOT_FOUND';
  end if;
  v_uid := public.kh_require_role(v_n.group_id, 'member');
  perform public.kh_require_active_group(v_n.group_id);
  select gm.role into v_role from public.group_members gm
  where gm.group_id = v_n.group_id and gm.user_id = v_uid and gm.status = 'active';
  if v_n.created_by <> v_uid and v_role not in ('owner', 'admin') then
    raise exception 'EDIT_NOT_ALLOWED' using errcode = '42501';
  end if;
  update public.group_notices set deleted_at = now(), deleted_by = v_uid where id = p_notice_id;
end;
$$;

revoke all on function public.get_shopping_list(uuid) from public, anon;
revoke all on function public.add_shopping_item(uuid, text, text) from public, anon;
revoke all on function public.set_shopping_item_status(uuid, boolean) from public, anon;
revoke all on function public.remove_shopping_item(uuid) from public, anon;
revoke all on function public.clear_bought_items(uuid) from public, anon;
revoke all on function public.list_notices(uuid) from public, anon;
revoke all on function public.create_notice(uuid, text, text, boolean) from public, anon;
revoke all on function public.update_notice(uuid, text, text, boolean) from public, anon;
revoke all on function public.delete_notice(uuid) from public, anon;

grant execute on function public.get_shopping_list(uuid) to authenticated;
grant execute on function public.add_shopping_item(uuid, text, text) to authenticated;
grant execute on function public.set_shopping_item_status(uuid, boolean) to authenticated;
grant execute on function public.remove_shopping_item(uuid) to authenticated;
grant execute on function public.clear_bought_items(uuid) to authenticated;
grant execute on function public.list_notices(uuid) to authenticated;
grant execute on function public.create_notice(uuid, text, text, boolean) to authenticated;
grant execute on function public.update_notice(uuid, text, text, boolean) to authenticated;
grant execute on function public.delete_notice(uuid) to authenticated;

commit;


-- ============================================================
-- 0006_storage_realtime.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0006 STORAGE BUCKETS + REALTIME
-- receipts  : PRIVATE bucket, path  <group_id>/<expense_id>/<file>
-- avatars   : public-read bucket, path <user_id>/<file>
-- ============================================================

begin;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('receipts', 'receipts', false, 5242880,
        array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- Receipts: only ACTIVE members of the group in the first path segment.
drop policy if exists khatafy_receipts_select on storage.objects;
create policy khatafy_receipts_select on storage.objects for select to authenticated
using (
  bucket_id = 'receipts'
  and public.is_group_member(public.try_uuid((storage.foldername(name))[1]))
);

drop policy if exists khatafy_receipts_insert on storage.objects;
create policy khatafy_receipts_insert on storage.objects for insert to authenticated
with check (
  bucket_id = 'receipts'
  and array_length(storage.foldername(name), 1) = 2
  and public.is_group_member(public.try_uuid((storage.foldername(name))[1]))
  and exists (
    select 1 from public.expenses e
    where e.id = public.try_uuid((storage.foldername(name))[2])
      and e.group_id = public.try_uuid((storage.foldername(name))[1])
      and e.status = 'active'
  )
);
-- No update/delete policies on receipts: files are evidence and are never overwritten or deleted by clients.

-- Avatars: anyone signed in may read; users only write inside their own folder.
drop policy if exists khatafy_avatars_select on storage.objects;
create policy khatafy_avatars_select on storage.objects for select to authenticated
using (bucket_id = 'avatars');

drop policy if exists khatafy_avatars_insert on storage.objects;
create policy khatafy_avatars_insert on storage.objects for insert to authenticated
with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists khatafy_avatars_update on storage.objects;
create policy khatafy_avatars_update on storage.objects for update to authenticated
using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text)
with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists khatafy_avatars_delete on storage.objects;
create policy khatafy_avatars_delete on storage.objects for delete to authenticated
using (bucket_id = 'avatars' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- Realtime: clients only receive rows their RLS select policies allow.
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['expenses', 'payments', 'group_members', 'join_requests',
                             'notifications', 'shopping_list_items', 'group_notices']
    loop
      if not exists (
        select 1 from pg_publication_tables pt
        where pt.pubname = 'supabase_realtime' and pt.schemaname = 'public' and pt.tablename = t
      ) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

commit;


-- ============================================================
-- 0007_account.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0007 ACCOUNT EXPORT + DELETION (privacy)
-- ============================================================

begin;

create or replace function public.export_my_data()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare v_uid uuid := public.kh_uid();
begin
  perform public.kh_rate_limit('export_data', 5, 3600);
  return jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) - 'deleted_at' from public.profiles p where p.id = v_uid),
    'memberships', coalesce((
      select jsonb_agg(jsonb_build_object(
        'group_id', gm.group_id, 'group_name', g.name, 'role', gm.role, 'status', gm.status,
        'joined_at', gm.joined_at, 'left_at', gm.left_at))
      from public.group_members gm join public.groups g on g.id = gm.group_id
      where gm.user_id = v_uid), '[]'::jsonb),
    'expenses_paid_or_created', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', e.id, 'group_id', e.group_id, 'title', e.title, 'amount_paise', e.amount_paise,
        'category', e.category_key, 'spent_at', e.spent_at, 'paid_by_me', e.paid_by = v_uid,
        'created_by_me', e.created_by = v_uid, 'status', e.status, 'note', e.note))
      from public.expenses e where e.paid_by = v_uid or e.created_by = v_uid), '[]'::jsonb),
    'my_expense_shares', coalesce((
      select jsonb_agg(jsonb_build_object(
        'expense_id', es.expense_id, 'group_id', es.group_id, 'share_paise', es.share_paise, 'version', es.version))
      from public.expense_splits es where es.user_id = v_uid), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pm.id, 'group_id', pm.group_id, 'from_user', pm.from_user, 'to_user', pm.to_user,
        'amount_paise', pm.amount_paise, 'method', pm.method, 'paid_at', pm.paid_at,
        'status', pm.status, 'reference', pm.reference, 'note', pm.note))
      from public.payments pm where pm.from_user = v_uid or pm.to_user = v_uid), '[]'::jsonb),
    'join_requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', jr.id, 'group_id', jr.group_id, 'status', jr.status, 'created_at', jr.created_at))
      from public.join_requests jr where jr.user_id = v_uid), '[]'::jsonb)
  );
end;
$$;

-- Anonymises the profile (financial history stays readable to other members as
-- "Deleted user"), removes the person from every group and deletes the login.
-- Group owners with other active members must transfer ownership first.
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
begin
  perform public.kh_rate_limit('delete_account', 5, 3600);

  if exists (
    select 1
    from public.group_members gm
    join public.groups g on g.id = gm.group_id
    where gm.user_id = v_uid and gm.status = 'active' and gm.role = 'owner' and g.status = 'active'
      and exists (select 1 from public.group_members o
                  where o.group_id = gm.group_id and o.status = 'active' and o.user_id <> v_uid)
  ) then
    raise exception 'OWNER_MUST_TRANSFER';
  end if;

  -- groups where the user is the only remaining member get archived
  update public.groups g set status = 'archived'
  where g.status = 'active'
    and exists (select 1 from public.group_members gm
                where gm.group_id = g.id and gm.user_id = v_uid and gm.status = 'active' and gm.role = 'owner')
    and not exists (select 1 from public.group_members o
                    where o.group_id = g.id and o.status = 'active' and o.user_id <> v_uid);
  update public.group_invitations gi set revoked_at = coalesce(gi.revoked_at, now())
  where gi.revoked_at is null
    and exists (select 1 from public.groups g where g.id = gi.group_id and g.status = 'archived');

  update public.join_requests
  set status = 'cancelled', reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
  where user_id = v_uid and status = 'pending';

  update public.payments
  set status = 'cancelled', decided_by = v_uid, decided_at = now(), decision_note = 'account deleted'
  where status = 'pending' and (from_user = v_uid or created_by = v_uid);

  update public.group_members set status = 'left', left_at = now()
  where user_id = v_uid and status = 'active';

  delete from public.push_tokens where user_id = v_uid;
  delete from public.notifications where user_id = v_uid;

  update public.profiles
  set full_name = 'Deleted user', phone = null, avatar_url = null, deleted_at = now()
  where id = v_uid;

  delete from auth.users where id = v_uid;
end;
$$;

revoke all on function public.export_my_data() from public, anon;
revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.export_my_data() to authenticated;
grant execute on function public.delete_my_account() to authenticated;

commit;


-- ============================================================
-- 0008_edit_window_statement.sql
-- ============================================================
-- ============================================================
-- KHATAFY | 0008: 1-hour edit window + date-range statement
-- ============================================================
begin;

-- 1. An expense can only be EDITED during the first hour after it was added.
--    (Cancelling/voiding stays possible at any time; the history is kept either way.)
--    The window length must match EDIT_WINDOW_MINUTES in packages/core/src/dates.ts.
create or replace function public.guard_expense_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare v_fin_changed boolean;
begin
  if old.status = 'voided' then
    raise exception 'EXPENSE_VOIDED';
  end if;
  if new.group_id <> old.group_id or new.created_by <> old.created_by
     or new.idempotency_key <> old.idempotency_key or new.created_at <> old.created_at then
    raise exception 'IMMUTABLE_RECORD';
  end if;

  v_fin_changed := (new.title, new.amount_paise, new.category_key, new.spent_at, new.paid_by, new.split_mode, new.note)
    is distinct from (old.title, old.amount_paise, old.category_key, old.spent_at, old.paid_by, old.split_mode, old.note);

  if new.status = 'voided' then
    if v_fin_changed or new.version <> old.version then
      raise exception 'IMMUTABLE_RECORD';
    end if;
  elsif v_fin_changed then
    if now() > old.created_at + interval '60 minutes' then
      raise exception 'EDIT_WINDOW_EXPIRED' using errcode = '42501';
    end if;
    if new.version <> old.version + 1 then
      raise exception 'VERSION_CONFLICT';
    end if;
  elsif new.version <> old.version then
    raise exception 'VERSION_CONFLICT';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

-- 2. Statement for a month / custom date range: every expense with who paid and who it was split on.
--    Dates are interpreted in the group's time zone (inclusive). Voided expenses are left out.
create or replace function public.get_group_statement(p_group_id uuid, p_from date, p_to date)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_tz text;
  v_name text;
  v_from timestamptz;
  v_to timestamptz;
  v_limit constant integer := 3000;
  v_count integer;
  v_exp jsonb;
  v_members jsonb;
  v_pay jsonb;
  v_total bigint;
begin
  perform public.kh_require_role(p_group_id, 'member');
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'INVALID_DATE_RANGE';
  end if;
  if p_to - p_from > 1100 then
    raise exception 'DATE_RANGE_TOO_LARGE';
  end if;
  select g.timezone, g.name into v_tz, v_name from public.groups g where g.id = p_group_id;
  v_from := p_from::timestamp at time zone v_tz;
  v_to := (p_to + 1)::timestamp at time zone v_tz;

  with ex as (
    select e.* from public.expenses e
    where e.group_id = p_group_id and e.status = 'active' and e.spent_at >= v_from and e.spent_at < v_to
    order by e.spent_at, e.id
    limit v_limit + 1
  )
  select count(*) into v_count from ex;

  with ex as (
    select e.* from public.expenses e
    where e.group_id = p_group_id and e.status = 'active' and e.spent_at >= v_from and e.spent_at < v_to
    order by e.spent_at, e.id
    limit v_limit
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id', ex.id, 'title', ex.title, 'category_key', ex.category_key, 'spent_at', ex.spent_at,
      'amount_paise', ex.amount_paise, 'paid_by', ex.paid_by,
      'paid_by_name', (select p.full_name from public.profiles p where p.id = ex.paid_by),
      'note', ex.note, 'version', ex.version, 'split_mode', ex.split_mode,
      'splits', coalesce((
        select jsonb_agg(jsonb_build_object('user_id', es.user_id, 'full_name', p.full_name, 'share_paise', es.share_paise)
                         order by p.full_name, es.user_id)
        from public.expense_splits es join public.profiles p on p.id = es.user_id
        where es.expense_id = ex.id and es.version = ex.version), '[]'::jsonb)
    ) order by ex.spent_at, ex.id), '[]'::jsonb),
    coalesce(sum(ex.amount_paise), 0)
  into v_exp, v_total
  from ex;

  with ex as (
    select e.id, e.paid_by, e.amount_paise, e.version from public.expenses e
    where e.group_id = p_group_id and e.status = 'active' and e.spent_at >= v_from and e.spent_at < v_to
    order by e.spent_at, e.id limit v_limit
  ), paid as (
    select ex.paid_by as user_id, sum(ex.amount_paise) as paid_paise from ex group by ex.paid_by
  ), shares as (
    select es.user_id, sum(es.share_paise) as share_paise
    from ex join public.expense_splits es on es.expense_id = ex.id and es.version = ex.version group by es.user_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'user_id', m.user_id, 'full_name', p.full_name, 'status', m.status,
      'paid_paise', coalesce(paid.paid_paise, 0), 'share_paise', coalesce(shares.share_paise, 0)
    ) order by p.full_name, m.user_id), '[]'::jsonb)
  into v_members
  from public.group_members m
  join public.profiles p on p.id = m.user_id
  left join paid on paid.user_id = m.user_id
  left join shares on shares.user_id = m.user_id
  where m.group_id = p_group_id
    and (m.status = 'active' or paid.paid_paise is not null or shares.share_paise is not null);

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', pm.id, 'from_user', pm.from_user, 'from_name', pf.full_name, 'to_user', pm.to_user, 'to_name', pt.full_name,
      'amount_paise', pm.amount_paise, 'paid_at', pm.paid_at, 'method', pm.method
    ) order by pm.paid_at, pm.id), '[]'::jsonb)
  into v_pay
  from public.payments pm
  join public.profiles pf on pf.id = pm.from_user
  join public.profiles pt on pt.id = pm.to_user
  where pm.group_id = p_group_id and pm.status = 'confirmed' and pm.paid_at >= v_from and pm.paid_at < v_to;

  return jsonb_build_object(
    'group_name', v_name, 'timezone', v_tz, 'from', p_from, 'to', p_to,
    'total_paise', v_total, 'expense_count', least(v_count, v_limit), 'truncated', v_count > v_limit,
    'expenses', v_exp, 'members', v_members, 'payments', v_pay
  );
end;
$$;

revoke all on function public.get_group_statement(uuid, date, date) from public, anon;
grant execute on function public.get_group_statement(uuid, date, date) to authenticated;

commit;


-- ============================================================
-- 0009_remove_owner_role.sql
-- ============================================================
-- Khatafy migration 0009: the "owner" role is removed.
-- * Everyone who was an owner becomes an admin; the person who creates a group is its first admin.
-- * Any admin can promote a member to admin. An admin can step down (only while another admin remains).
-- * Admins cannot demote or remove each other. The last admin cannot leave / delete the account while
--   other members remain - promote someone first.
-- Safe to run once on an existing project (needs 0001-0008).
begin;

drop index if exists public.uq_group_one_active_owner;
update public.group_members set role = 'admin' where role = 'owner';
alter table public.group_members drop constraint if exists group_members_role_check;
alter table public.group_members add constraint group_members_role_check check (role in ('admin', 'member'));

-- the creator is the first admin
create or replace function public.create_group(p_name text, p_description text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_group_id uuid;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if p_name is null or char_length(trim(p_name)) not between 2 and 80 then
    raise exception 'Group name must be between 2 and 80 characters';
  end if;
  if p_description is not null and char_length(p_description) > 500 then
    raise exception 'Description is too long';
  end if;
  insert into public.groups (name, description, created_by)
  values (trim(p_name), nullif(trim(p_description), ''), v_user_id)
  returning id into v_group_id;
  insert into public.group_members (group_id, user_id, role, status)
  values (v_group_id, v_user_id, 'admin', 'active');
  return v_group_id;
end;
$$;

-- an admin may leave only while another admin remains
create or replace function public.leave_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_role text;
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  select gm.role into v_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_user_id and gm.status = 'active'
  for update;
  if v_role is null then
    raise exception 'Active membership not found';
  end if;
  if v_role = 'admin' and not exists (
    select 1 from public.group_members o
    where o.group_id = p_group_id and o.status = 'active' and o.role = 'admin' and o.user_id <> v_user_id
  ) then
    raise exception 'LAST_ADMIN';
  end if;
  update public.group_members set status = 'left', left_at = now()
  where group_id = p_group_id and user_id = v_user_id and status = 'active';
end;
$$;

-- any admin removes members; admins cannot remove each other
create or replace function public.remove_group_member(p_group_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_actor_role text;
  v_target_role text;
begin
  if v_actor_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if v_actor_id = p_user_id then
    raise exception 'Use leave_group to leave voluntarily';
  end if;
  select gm.role into v_actor_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_actor_id and gm.status = 'active';
  if v_actor_role is distinct from 'admin' then
    raise exception 'Only group admins can remove members' using errcode = '42501';
  end if;
  select gm.role into v_target_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = p_user_id and gm.status = 'active'
  for update;
  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;
  if v_target_role = 'admin' then
    raise exception 'ADMIN_CANNOT_BE_REMOVED';
  end if;
  update public.group_members set status = 'removed', left_at = now()
  where group_id = p_group_id and user_id = p_user_id and status = 'active';
end;
$$;

create or replace function public.archive_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'admin');
  update public.groups set status = 'archived' where id = p_group_id and status = 'active';
  update public.group_invitations set revoked_at = coalesce(revoked_at, now())
  where group_id = p_group_id and revoked_at is null;
end;
$$;

-- admin promotes a member; an admin can only step down himself/herself, and only if another admin remains
create or replace function public.set_group_member_role(p_group_id uuid, p_user_id uuid, p_new_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid;
  v_target_role text;
  v_group_name text;
  v_actor_name text;
begin
  v_actor := public.kh_require_role(p_group_id, 'admin');
  perform public.kh_require_active_group(p_group_id);
  if p_new_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member';
  end if;
  select gm.role into v_target_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = p_user_id and gm.status = 'active'
  for update;
  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;
  if v_target_role = p_new_role then
    return;
  end if;
  if p_new_role = 'member' then
    if p_user_id <> v_actor then
      raise exception 'ADMIN_CANNOT_BE_DEMOTED';
    end if;
    if not exists (
      select 1 from public.group_members o
      where o.group_id = p_group_id and o.status = 'active' and o.role = 'admin' and o.user_id <> v_actor
    ) then
      raise exception 'LAST_ADMIN';
    end if;
  end if;
  update public.group_members set role = p_new_role
  where group_id = p_group_id and user_id = p_user_id and status = 'active';
  if p_new_role = 'admin' then
    select g.name into v_group_name from public.groups g where g.id = p_group_id;
    select p.full_name into v_actor_name from public.profiles p where p.id = v_actor;
    perform public.kh_notify(p_user_id, p_group_id, 'admin_granted',
      jsonb_build_object('group_name', v_group_name, 'name', v_actor_name), null);
  end if;
end;
$$;

-- ownership no longer exists
drop function if exists public.transfer_group_ownership(uuid, uuid);
drop function if exists public.is_group_owner(uuid);

create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_uid();
begin
  perform public.kh_rate_limit('delete_account', 5, 3600);

  -- the last admin of a group that still has other members must hand over first
  if exists (
    select 1
    from public.group_members gm
    join public.groups g on g.id = gm.group_id
    where gm.user_id = v_uid and gm.status = 'active' and gm.role = 'admin' and g.status = 'active'
      and exists (select 1 from public.group_members o
                  where o.group_id = gm.group_id and o.status = 'active' and o.user_id <> v_uid)
      and not exists (select 1 from public.group_members o
                  where o.group_id = gm.group_id and o.status = 'active' and o.user_id <> v_uid and o.role = 'admin')
  ) then
    raise exception 'LAST_ADMIN';
  end if;

  -- groups where the user is the only remaining member get archived
  update public.groups g set status = 'archived'
  where g.status = 'active'
    and exists (select 1 from public.group_members gm
                where gm.group_id = g.id and gm.user_id = v_uid and gm.status = 'active' and gm.role = 'admin')
    and not exists (select 1 from public.group_members o
                    where o.group_id = g.id and o.status = 'active' and o.user_id <> v_uid);
  update public.group_invitations gi set revoked_at = coalesce(gi.revoked_at, now())
  where gi.revoked_at is null
    and exists (select 1 from public.groups g where g.id = gi.group_id and g.status = 'archived');

  update public.join_requests
  set status = 'cancelled', reviewed_by = v_uid, reviewed_at = now(), updated_at = now()
  where user_id = v_uid and status = 'pending';

  update public.payments
  set status = 'cancelled', decided_by = v_uid, decided_at = now(), decision_note = 'account deleted'
  where status = 'pending' and (from_user = v_uid or created_by = v_uid);

  update public.group_members set status = 'left', left_at = now()
  where user_id = v_uid and status = 'active';

  delete from public.push_tokens where user_id = v_uid;
  delete from public.notifications where user_id = v_uid;

  update public.profiles
  set full_name = 'Deleted user', phone = null, avatar_url = null, deleted_at = now()
  where id = v_uid;

  delete from auth.users where id = v_uid;
end;
$$;

revoke all on function public.create_group(text, text) from public, anon;
revoke all on function public.leave_group(uuid) from public, anon;
revoke all on function public.remove_group_member(uuid, uuid) from public, anon;
revoke all on function public.archive_group(uuid) from public, anon;
revoke all on function public.set_group_member_role(uuid, uuid, text) from public, anon;
revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.create_group(text, text) to authenticated;
grant execute on function public.leave_group(uuid) to authenticated;
grant execute on function public.remove_group_member(uuid, uuid) to authenticated;
grant execute on function public.archive_group(uuid) to authenticated;
grant execute on function public.set_group_member_role(uuid, uuid, text) to authenticated;
grant execute on function public.delete_my_account() to authenticated;

commit;


-- ============================================================
-- 0010_creator_can_remove_admins.sql
-- ============================================================
-- Khatafy migration 0010: the person who created a group (its first admin) can also demote / remove
-- other admins. Other admins still cannot demote or remove each other, and nobody can remove or demote
-- the creator (the creator can only step down himself/herself while another admin remains).
-- There is still no "owner" role: this is only a rule about the group's creator.
begin;

create or replace function public.get_group(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := public.kh_require_role(p_group_id, 'member');
  v_role text;
begin
  select gm.role into v_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';

  return (
    select jsonb_build_object(
      'id', g.id, 'name', g.name, 'description', g.description, 'status', g.status,
      'currency_code', g.currency_code, 'timezone', g.timezone, 'created_at', g.created_at,
      'created_by', g.created_by,
      'my_role', v_role,
      'member_count', (select count(*) from public.group_members m where m.group_id = g.id and m.status = 'active'),
      'pending_requests', case when v_role = 'admin'
        then (select count(*) from public.join_requests jr where jr.group_id = g.id and jr.status = 'pending') else 0 end
    )
    from public.groups g where g.id = p_group_id
  );
end;
$$;

create or replace function public.remove_group_member(p_group_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor_id uuid := (select auth.uid());
  v_actor_role text;
  v_target_role text;
  v_creator uuid;
begin
  if v_actor_id is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;
  if v_actor_id = p_user_id then
    raise exception 'Use leave_group to leave voluntarily';
  end if;
  select gm.role into v_actor_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = v_actor_id and gm.status = 'active';
  if v_actor_role is distinct from 'admin' then
    raise exception 'Only group admins can remove members' using errcode = '42501';
  end if;
  select g.created_by into v_creator from public.groups g where g.id = p_group_id;
  select gm.role into v_target_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = p_user_id and gm.status = 'active'
  for update;
  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;
  -- the creator can never be removed; other admins only by the creator
  if p_user_id = v_creator or (v_target_role = 'admin' and v_actor_id is distinct from v_creator) then
    raise exception 'ADMIN_CANNOT_BE_REMOVED';
  end if;
  update public.group_members set status = 'removed', left_at = now()
  where group_id = p_group_id and user_id = p_user_id and status = 'active';
end;
$$;

create or replace function public.set_group_member_role(p_group_id uuid, p_user_id uuid, p_new_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid;
  v_target_role text;
  v_creator uuid;
  v_group_name text;
  v_actor_name text;
begin
  v_actor := public.kh_require_role(p_group_id, 'admin');
  perform public.kh_require_active_group(p_group_id);
  if p_new_role not in ('admin', 'member') then
    raise exception 'Role must be admin or member';
  end if;
  select g.created_by into v_creator from public.groups g where g.id = p_group_id;
  select gm.role into v_target_role from public.group_members gm
  where gm.group_id = p_group_id and gm.user_id = p_user_id and gm.status = 'active'
  for update;
  if v_target_role is null then
    raise exception 'Active target membership not found';
  end if;
  if v_target_role = p_new_role then
    return;
  end if;
  if p_new_role = 'member' then
    -- the creator may demote any other admin; everyone may step down themselves
    if p_user_id <> v_actor and v_actor is distinct from v_creator then
      raise exception 'ADMIN_CANNOT_BE_DEMOTED';
    end if;
    if not exists (
      select 1 from public.group_members o
      where o.group_id = p_group_id and o.status = 'active' and o.role = 'admin' and o.user_id <> p_user_id
    ) then
      raise exception 'LAST_ADMIN';
    end if;
  end if;
  update public.group_members set role = p_new_role
  where group_id = p_group_id and user_id = p_user_id and status = 'active';
  if p_new_role = 'admin' then
    select g.name into v_group_name from public.groups g where g.id = p_group_id;
    select p.full_name into v_actor_name from public.profiles p where p.id = v_actor;
    perform public.kh_notify(p_user_id, p_group_id, 'admin_granted',
      jsonb_build_object('group_name', v_group_name, 'name', v_actor_name), null);
  end if;
end;
$$;

revoke all on function public.get_group(uuid) from public, anon;
revoke all on function public.remove_group_member(uuid, uuid) from public, anon;
revoke all on function public.set_group_member_role(uuid, uuid, text) from public, anon;
grant execute on function public.get_group(uuid) to authenticated;
grant execute on function public.remove_group_member(uuid, uuid) to authenticated;
grant execute on function public.set_group_member_role(uuid, uuid, text) to authenticated;

commit;


-- ============================================================
-- 0011_notif_delete_admin_panel.sql
-- ============================================================
-- 0011: notification delete + privacy-preserving platform admin panel.
-- Platform admins see ONLY aggregate numbers and technical group metadata (no names, emails,
-- expenses, amounts, notes or receipts). Every admin write needs a reason and is logged.

-- ---------- 1. Users can delete their own notifications ----------
create or replace function public.delete_notifications(p_ids bigint[] default null)
returns integer language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_uid(); v_n integer;
begin
  delete from public.notifications n where n.user_id = v_uid and (p_ids is null or n.id = any (p_ids));
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- ---------- 2. Platform admin tables (no client access at all) ----------
create table if not exists public.platform_admins (
  user_id uuid primary key references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
create table if not exists public.app_settings (
  key text primary key check (key in ('maintenance', 'announcement')),
  value jsonb not null,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);
create table if not exists public.platform_audit (
  id bigint generated always as identity primary key,
  actor_id uuid references auth.users(id) on delete set null,
  action text not null,
  target text,
  reason text,
  created_at timestamptz not null default now()
);
alter table public.platform_admins enable row level security;
alter table public.app_settings enable row level security;
alter table public.platform_audit enable row level security;
revoke all on public.platform_admins, public.app_settings, public.platform_audit from anon, authenticated;
insert into public.app_settings(key, value) values ('maintenance', 'false'::jsonb), ('announcement', '""'::jsonb)
  on conflict (key) do nothing;

create or replace function public.kh_admin_uid()
returns uuid language plpgsql stable security definer set search_path = '' as $$
declare v_uid uuid := public.kh_uid();
begin
  if not exists (select 1 from public.platform_admins a where a.user_id = v_uid) then
    raise exception 'NOT_PLATFORM_ADMIN' using errcode = '42501';
  end if;
  return v_uid;
end $$;

create or replace function public.am_i_platform_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.platform_admins a where a.user_id = (select auth.uid()));
$$;

-- Public (works before login): only a maintenance flag and a short announcement text.
create or replace function public.get_app_status()
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'maintenance', coalesce((select (value)::text = 'true' from public.app_settings where key = 'maintenance'), false),
    'announcement', coalesce((select value #>> '{}' from public.app_settings where key = 'announcement'), ''));
$$;

-- ---------- 3. Admin RPCs: aggregates only ----------
create or replace function public.admin_overview()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_days jsonb;
begin
  perform public.kh_admin_uid();
  select coalesce(jsonb_agg(jsonb_build_object('day', d::date, 'signups',
           (select count(*) from public.profiles p where p.created_at::date = d::date)) order by d), '[]'::jsonb)
    into v_days from generate_series(current_date - 13, current_date, interval '1 day') d;
  return jsonb_build_object(
    'users_total', (select count(*) from public.profiles),
    'users_7d', (select count(*) from public.profiles where created_at > now() - interval '7 days'),
    'users_30d', (select count(*) from public.profiles where created_at > now() - interval '30 days'),
    'groups_total', (select count(*) from public.groups),
    'groups_active', (select count(*) from public.groups where status = 'active'),
    'groups_archived', (select count(*) from public.groups where status = 'archived'),
    'expenses_30d', (select count(*) from public.expenses where created_at > now() - interval '30 days' and status = 'active'),
    'payments_30d', (select count(*) from public.payments where created_at > now() - interval '30 days'),
    'signups_14d', v_days);
end $$;

-- Technical metadata only: NO group name, NO member names, NO amounts.
create or replace function public.admin_list_groups(p_limit integer default 50, p_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.kh_admin_uid();
  return coalesce((select jsonb_agg(x) from (
    select g.id, g.status, g.created_at,
      (select count(*) from public.group_members m where m.group_id = g.id and m.status = 'active') as members,
      (select count(*) from public.expenses e where e.group_id = g.id and e.created_at > now() - interval '30 days') as expenses_30d
    from public.groups g order by g.created_at desc
    limit least(greatest(p_limit, 1), 100) offset greatest(p_offset, 0)) x), '[]'::jsonb);
end $$;

-- Archive (make read-only) or restore a group, e.g. after a legal / abuse complaint. Reason is mandatory.
create or replace function public.admin_set_group_status(p_group_id uuid, p_status text, p_reason text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_admin_uid();
begin
  if p_status not in ('active', 'archived') then raise exception 'INVALID_STATUS'; end if;
  if p_reason is null or char_length(trim(p_reason)) < 10 or char_length(p_reason) > 300 then raise exception 'REASON_REQUIRED'; end if;
  update public.groups set status = p_status where id = p_group_id;
  if not found then raise exception 'GROUP_NOT_FOUND'; end if;
  insert into public.platform_audit(actor_id, action, target, reason)
  values (v_uid, 'group_' || p_status, p_group_id::text, trim(p_reason));
end $$;

create or replace function public.admin_set_app_status(p_maintenance boolean, p_announcement text)
returns void language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_admin_uid(); v_text text := left(trim(coalesce(p_announcement, '')), 300);
begin
  update public.app_settings set value = to_jsonb(coalesce(p_maintenance, false)), updated_at = now(), updated_by = v_uid where key = 'maintenance';
  update public.app_settings set value = to_jsonb(v_text), updated_at = now(), updated_by = v_uid where key = 'announcement';
  insert into public.platform_audit(actor_id, action, target, reason)
  values (v_uid, 'app_status', null, 'maintenance=' || coalesce(p_maintenance, false)::text);
end $$;

create or replace function public.admin_list_audit(p_limit integer default 50)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  perform public.kh_admin_uid();
  return coalesce((select jsonb_agg(x) from (
    select id, action, target, reason, created_at from public.platform_audit order by id desc limit least(greatest(p_limit, 1), 200)) x), '[]'::jsonb);
end $$;

-- ---------- 4. Grants ----------
revoke all on function public.delete_notifications(bigint[]) from public, anon;
revoke all on function public.kh_admin_uid() from public, anon, authenticated;
revoke all on function public.am_i_platform_admin() from public, anon;
revoke all on function public.get_app_status() from public;
revoke all on function public.admin_overview() from public, anon;
revoke all on function public.admin_list_groups(integer, integer) from public, anon;
revoke all on function public.admin_set_group_status(uuid, text, text) from public, anon;
revoke all on function public.admin_set_app_status(boolean, text) from public, anon;
revoke all on function public.admin_list_audit(integer) from public, anon;
grant execute on function public.delete_notifications(bigint[]) to authenticated;
grant execute on function public.am_i_platform_admin() to authenticated;
grant execute on function public.get_app_status() to anon, authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_list_groups(integer, integer) to authenticated;
grant execute on function public.admin_set_group_status(uuid, text, text) to authenticated;
grant execute on function public.admin_set_app_status(boolean, text) to authenticated;
grant execute on function public.admin_list_audit(integer) to authenticated;

-- First admin (run ONCE in the SQL editor, with YOUR email; there is deliberately no UI/API to grant admin):
--   insert into public.platform_admins(user_id) select id from auth.users where email = 'you@example.com';


-- ============================================================
-- 0012_security_hardening.sql
-- ============================================================
-- 0012: security hardening.
-- The "export my data" button was removed from the app (it exposed internal IDs). Close the server side too,
-- so nobody can call it directly with the public anon key + a stolen session. Re-enable only with a reviewed,
-- ID-free export design.
revoke execute on function public.export_my_data() from authenticated;


-- ============================================================
-- 0013_retention_auto_delete.sql
-- ============================================================
-- 0013: owner-controlled auto-delete (data retention) with balance carry-forward.
-- * Only the group OWNER can set it (6 / 9 / 12 months, or off). Default: off.
-- * 7-day grace period after every change; all members are notified.
-- * Old expenses, payments, notices, shopping items, notifications and audit rows are deleted by a daily job.
-- * Balances stay correct: the net effect of deleted records is stored in group_balance_carry (amounts only, no details).
-- * Receipt FILES are queued in storage_cleanup_queue and removed by the purge-receipts Edge Function (see README).
begin;

alter table public.groups add column if not exists retention_months smallint
  check (retention_months is null or retention_months in (6, 9, 12));
alter table public.groups add column if not exists retention_effective_at timestamptz;

create table if not exists public.group_balance_carry (
  group_id uuid not null references public.groups(id) on delete cascade,
  user_id uuid not null references public.profiles(id),
  carry_paise bigint not null,
  updated_at timestamptz not null default now(),
  primary key (group_id, user_id)
);
create table if not exists public.storage_cleanup_queue (
  id bigint generated always as identity primary key,
  bucket text not null default 'receipts',
  storage_path text not null,
  queued_at timestamptz not null default now(),
  done_at timestamptz
);
alter table public.group_balance_carry enable row level security;
alter table public.storage_cleanup_queue enable row level security;
revoke all on public.group_balance_carry, public.storage_cleanup_queue from anon, authenticated;

-- Allow deletes ONLY inside the purge job (it sets a transaction-local flag clients cannot set).
create or replace function public.block_hard_delete()
returns trigger language plpgsql set search_path = '' as $$
begin
  if current_setting('khatafy.purge', true) = 'on' then return old; end if;
  raise exception 'HARD_DELETE_FORBIDDEN' using hint = 'Financial records are void/reverse only.';
end;
$$;

-- Balances now include the carry-forward (lifetime view only).
create or replace function public.get_group_balances(
  p_group_id uuid, p_from timestamptz default null, p_to timestamptz default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform public.kh_require_role(p_group_id, 'member');
  return coalesce((
    with members as (
      select distinct on (gm.user_id) gm.user_id, gm.status
      from public.group_members gm
      where gm.group_id = p_group_id
      order by gm.user_id, (gm.status = 'active') desc, gm.joined_at desc
    ),
    exp as (
      select e.id, e.version, e.paid_by, e.amount_paise
      from public.expenses e
      where e.group_id = p_group_id and e.status = 'active'
        and (p_from is null or e.spent_at >= p_from) and (p_to is null or e.spent_at < p_to)
    ),
    carry as (
      select c.user_id as uid, c.carry_paise as s from public.group_balance_carry c
      where c.group_id = p_group_id and p_from is null
    ),
    paid as (select x.paid_by as uid, sum(x.amount_paise) as s from exp x group by x.paid_by),
    shares as (
      select es.user_id as uid, sum(es.share_paise) as s
      from public.expense_splits es join exp x on x.id = es.expense_id and x.version = es.version
      group by es.user_id
    ),
    pay as (
      select pm.from_user, pm.to_user, pm.amount_paise
      from public.payments pm
      where pm.group_id = p_group_id and pm.status = 'confirmed'
        and (p_from is null or pm.paid_at >= p_from) and (p_to is null or pm.paid_at < p_to)
    ),
    pout as (select from_user as uid, sum(amount_paise) as s from pay group by from_user),
    pin as (select to_user as uid, sum(amount_paise) as s from pay group by to_user),
    rows as (
      select m.user_id, m.status,
             coalesce(pd.s, 0) as paid_paise,
             coalesce(sh.s, 0) as share_paise,
             coalesce(po.s, 0) as settlement_paid_paise,
             coalesce(pi.s, 0) as settlement_received_paise,
             coalesce(cy.s, 0) as carry_paise
      from members m
      left join paid pd on pd.uid = m.user_id
      left join shares sh on sh.uid = m.user_id
      left join pout po on po.uid = m.user_id
      left join pin pi on pi.uid = m.user_id
      left join carry cy on cy.uid = m.user_id
    )
    select jsonb_agg(jsonb_build_object(
      'user_id', r.user_id, 'full_name', p.full_name, 'is_deleted', p.deleted_at is not null,
      'status', r.status,
      'paid_paise', r.paid_paise, 'share_paise', r.share_paise,
      'settlement_paid_paise', r.settlement_paid_paise,
      'settlement_received_paise', r.settlement_received_paise,
      'carry_paise', r.carry_paise,
      'net_paise', r.paid_paise - r.share_paise + r.settlement_paid_paise - r.settlement_received_paise + r.carry_paise
    ) order by (r.status = 'active') desc, lower(p.full_name))
    from rows r join public.profiles p on p.id = r.user_id
    where r.status = 'active'
       or r.paid_paise <> 0 or r.share_paise <> 0 or r.settlement_paid_paise <> 0 or r.settlement_received_paise <> 0 or r.carry_paise <> 0
  ), '[]'::jsonb);
end;
$$;


create or replace function public.get_group_retention(p_group_id uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_uid uuid := public.kh_require_role(p_group_id, 'member'); v_role text;
begin
  select gm.role into v_role from public.group_members gm where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active';
  return (select jsonb_build_object('months', g.retention_months, 'effective_at', g.retention_effective_at, 'can_edit', v_role = 'owner')
          from public.groups g where g.id = p_group_id);
end $$;

create or replace function public.set_group_retention(p_group_id uuid, p_months integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_require_role(p_group_id, 'owner'); v_name text; m record; v_eff timestamptz;
begin
  perform public.kh_require_active_group(p_group_id);
  if p_months is not null and p_months not in (6, 9, 12) then raise exception 'INVALID_RETENTION'; end if;
  v_eff := case when p_months is null then null else now() + interval '7 days' end;
  update public.groups set retention_months = p_months, retention_effective_at = v_eff where id = p_group_id;
  perform public.kh_audit(p_group_id, 'retention_changed', 'group', p_group_id::text, jsonb_build_object('months', p_months));
  select full_name into v_name from public.profiles where id = v_uid;
  for m in select gm.user_id from public.group_members gm where gm.group_id = p_group_id and gm.status = 'active' and gm.user_id <> v_uid loop
    perform public.kh_notify(m.user_id, p_group_id, case when p_months is null then 'retention_off' else 'retention_on' end,
      jsonb_build_object('name', v_name, 'months', p_months));
  end loop;
  return jsonb_build_object('months', p_months, 'effective_at', v_eff);
end $$;

-- Daily job. Internal only (not callable by clients).
create or replace function public.kh_purge_expired_data()
returns jsonb language plpgsql security definer set search_path = '' as $$
declare g record; v_cut timestamptz; n_exp int; n_pay int; n_misc int; t_exp int := 0; t_pay int := 0;
begin
  perform set_config('khatafy.purge', 'on', true);
  for g in select id, retention_months from public.groups
           where retention_months is not null and retention_effective_at is not null and retention_effective_at <= now() loop
    v_cut := now() - make_interval(months => g.retention_months);

    -- 1) keep balances correct: store the net effect of what is about to be removed
    with old_exp as (
      select e.id, e.version, e.paid_by, e.amount_paise from public.expenses e
      where e.group_id = g.id and e.status = 'active' and e.spent_at < v_cut),
    d as (
      select x.paid_by as uid, x.amount_paise as amt from old_exp x
      union all select es.user_id, -es.share_paise from public.expense_splits es
                join old_exp x on x.id = es.expense_id and x.version = es.version where es.group_id = g.id
      union all select pm.from_user, pm.amount_paise from public.payments pm where pm.group_id = g.id and pm.status = 'confirmed' and pm.paid_at < v_cut
      union all select pm.to_user, -pm.amount_paise from public.payments pm where pm.group_id = g.id and pm.status = 'confirmed' and pm.paid_at < v_cut),
    s as (select uid, sum(amt)::bigint as net from d group by uid having sum(amt) <> 0)
    insert into public.group_balance_carry (group_id, user_id, carry_paise)
    select g.id, s.uid, s.net from s
    on conflict (group_id, user_id) do update
      set carry_paise = public.group_balance_carry.carry_paise + excluded.carry_paise, updated_at = now();

    -- 2) queue receipt files, then delete rows (children first)
    insert into public.storage_cleanup_queue (storage_path)
      select r.storage_path from public.expense_receipts r join public.expenses e on e.id = r.expense_id and e.group_id = r.group_id
      where e.group_id = g.id and e.spent_at < v_cut;
    delete from public.expense_receipts r using public.expenses e where r.expense_id = e.id and r.group_id = e.group_id and e.group_id = g.id and e.spent_at < v_cut;
    delete from public.expense_revisions r using public.expenses e where r.expense_id = e.id and r.group_id = e.group_id and e.group_id = g.id and e.spent_at < v_cut;
    delete from public.expense_splits s2 using public.expenses e where s2.expense_id = e.id and s2.group_id = e.group_id and e.group_id = g.id and e.spent_at < v_cut;
    delete from public.expenses where group_id = g.id and spent_at < v_cut;
    get diagnostics n_exp = row_count;
    delete from public.payments where group_id = g.id and paid_at < v_cut;
    get diagnostics n_pay = row_count;
    delete from public.group_notices where group_id = g.id and created_at < v_cut and pinned = false;
    delete from public.shopping_list_items where group_id = g.id and created_at < v_cut;
    delete from public.notifications where group_id = g.id and created_at < v_cut;
    delete from public.audit_logs where group_id = g.id and created_at < v_cut and action <> 'retention_purge';
    get diagnostics n_misc = row_count;

    if n_exp > 0 or n_pay > 0 then
      perform public.kh_audit(g.id, 'retention_purge', 'group', g.id::text,
        jsonb_build_object('months', g.retention_months, 'expenses', n_exp, 'payments', n_pay));
    end if;
    t_exp := t_exp + n_exp; t_pay := t_pay + n_pay;
  end loop;
  return jsonb_build_object('expenses_deleted', t_exp, 'payments_deleted', t_pay);
end $$;

revoke all on function public.get_group_retention(uuid) from public, anon;
revoke all on function public.set_group_retention(uuid, integer) from public, anon;
revoke all on function public.kh_purge_expired_data() from public, anon, authenticated;
grant execute on function public.get_group_retention(uuid) to authenticated;
grant execute on function public.set_group_retention(uuid, integer) to authenticated;

-- Schedule the daily job (03:00 India time) if pg_cron is enabled (Dashboard -> Integrations -> Cron / Database -> Extensions).
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin perform cron.unschedule('khatafy-retention-purge'); exception when others then null; end;
    perform cron.schedule('khatafy-retention-purge', '30 21 * * *', 'select public.kh_purge_expired_data()');
  else
    raise notice 'pg_cron is not enabled: enable it, then re-run this block (see README) or the auto-delete will not run.';
  end if;
end $$;

commit;


-- ============================================================
-- 0014_period_close.sql
-- ============================================================
-- 0014: "Close period" (settle & close) replaces the time-based auto-delete of 0013.
-- Flow: admin/owner requests a close up to a date -> every member is notified -> 7-day review window
-- (any member can object; admin/owner can cancel) -> a daily job finalises: a permanent SUMMARY is stored,
-- remaining dues are carried forward as a balance (never lost), then the detailed expenses/payments are deleted.
begin;

-- ---------- 0. Remove the time-based retention from 0013 (safe if 0013 was never applied) ----------
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin perform cron.unschedule('khatafy-retention-purge'); exception when others then null; end;
  end if;
end $$;
drop function if exists public.set_group_retention(uuid, integer);
drop function if exists public.get_group_retention(uuid);
drop function if exists public.kh_purge_expired_data();
alter table public.groups drop column if exists retention_months;
alter table public.groups drop column if exists retention_effective_at;
-- foundation kept from 0013: group_balance_carry, storage_cleanup_queue, block_hard_delete bypass, get_group_balances(carry)
create table if not exists public.group_balance_carry (
  group_id uuid not null references public.groups(id) on delete cascade,
  user_id uuid not null references public.profiles(id),
  carry_paise bigint not null,
  updated_at timestamptz not null default now(),
  primary key (group_id, user_id));
create table if not exists public.storage_cleanup_queue (
  id bigint generated always as identity primary key, bucket text not null default 'receipts',
  storage_path text not null, queued_at timestamptz not null default now(), done_at timestamptz);
alter table public.group_balance_carry enable row level security;
alter table public.storage_cleanup_queue enable row level security;
revoke all on public.group_balance_carry, public.storage_cleanup_queue from anon, authenticated;

-- ---------- 1. Tables ----------
create table if not exists public.period_closes (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups(id) on delete cascade,
  period_end date not null,                       -- inclusive, in the group's timezone
  cut_at timestamptz not null,                    -- start of the day after period_end
  status text not null default 'pending' check (status in ('pending', 'closed', 'cancelled')),
  requested_by uuid not null references public.profiles(id),
  requested_at timestamptz not null default now(),
  effective_at timestamptz not null,
  closed_at timestamptz,
  summary jsonb
);
create unique index if not exists uq_period_close_one_pending on public.period_closes(group_id) where status = 'pending';
create index if not exists idx_period_closes_group on public.period_closes(group_id, cut_at desc);
create table if not exists public.period_close_objections (
  close_id uuid not null references public.period_closes(id) on delete cascade,
  user_id uuid not null references public.profiles(id),
  reason text not null check (char_length(trim(reason)) between 3 and 300),
  created_at timestamptz not null default now(),
  primary key (close_id, user_id));
alter table public.period_closes enable row level security;
alter table public.period_close_objections enable row level security;
revoke all on public.period_closes, public.period_close_objections from anon, authenticated;

-- ---------- 2. Closed periods are read-only: no new/back-dated records before the cut ----------
create or replace function public.guard_closed_period()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_col text := case tg_table_name when 'expenses' then 'spent_at' else 'paid_at' end;
        v_ts timestamptz; v_cut timestamptz;
begin
  if tg_op = 'UPDATE' and (to_jsonb(new) ->> v_col) is not distinct from (to_jsonb(old) ->> v_col) then return new; end if;
  v_ts := (to_jsonb(new) ->> v_col)::timestamptz;
  select max(c.cut_at) into v_cut from public.period_closes c where c.group_id = new.group_id and c.status = 'closed';
  if v_cut is not null and v_ts < v_cut then raise exception 'PERIOD_CLOSED'; end if;
  return new;
end $$;
drop trigger if exists trg_expenses_closed_period on public.expenses;
create trigger trg_expenses_closed_period before insert or update on public.expenses for each row execute function public.guard_closed_period();
drop trigger if exists trg_payments_closed_period on public.payments;
create trigger trg_payments_closed_period before insert or update on public.payments for each row execute function public.guard_closed_period();

revoke all on function public.guard_closed_period() from public, anon, authenticated;

-- ---------- 3. Summary (used for the live preview and for the final stored summary) ----------
create or replace function public.kh_close_summary(p_group_id uuid, p_cut timestamptz)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  return (
    with exp as (select e.id, e.version, e.paid_by, e.amount_paise, e.spent_at from public.expenses e
                 where e.group_id = p_group_id and e.status = 'active' and e.spent_at < p_cut),
    paid as (select x.paid_by as uid, sum(x.amount_paise) as s from exp x group by x.paid_by),
    shares as (select es.user_id as uid, sum(es.share_paise) as s from public.expense_splits es
               join exp x on x.id = es.expense_id and x.version = es.version where es.group_id = p_group_id group by es.user_id),
    pays as (select pm.from_user, pm.to_user, pm.amount_paise, pm.method, pm.paid_at from public.payments pm
             where pm.group_id = p_group_id and pm.status = 'confirmed' and pm.paid_at < p_cut),
    pout as (select from_user as uid, sum(amount_paise) as s from pays group by from_user),
    pin as (select to_user as uid, sum(amount_paise) as s from pays group by to_user),
    carry as (select c.user_id as uid, c.carry_paise as s from public.group_balance_carry c where c.group_id = p_group_id),
    people as (select uid from paid union select uid from shares union select uid from pout union select uid from pin union select uid from carry),
    rows as (
      select pe.uid, coalesce(pd.s, 0) as paid, coalesce(sh.s, 0) as share,
             coalesce(pd.s, 0) - coalesce(sh.s, 0) + coalesce(po.s, 0) - coalesce(pi.s, 0) + coalesce(cy.s, 0) as net
      from people pe left join paid pd on pd.uid = pe.uid left join shares sh on sh.uid = pe.uid
      left join pout po on po.uid = pe.uid left join pin pi on pi.uid = pe.uid left join carry cy on cy.uid = pe.uid)
    select jsonb_build_object(
      'from_date', (select min(spent_at) from exp),
      'to_date', p_cut - interval '1 second',
      'total_paise', coalesce((select sum(amount_paise) from exp), 0),
      'expense_count', (select count(*) from exp),
      'per_head_paise', coalesce((select round(sum(amount_paise)::numeric / nullif((select count(*) from rows where share > 0), 0)) from exp), 0),
      'members', coalesce((select jsonb_agg(jsonb_build_object('user_id', r.uid, 'name', p.full_name,
                   'paid_paise', r.paid, 'share_paise', r.share, 'net_paise', r.net) order by lower(p.full_name))
                 from rows r join public.profiles p on p.id = r.uid), '[]'::jsonb),
      'payments', coalesce((select jsonb_agg(jsonb_build_object('from_name', pf.full_name, 'to_name', pt.full_name,
                   'amount_paise', y.amount_paise, 'method', y.method, 'paid_at', y.paid_at) order by y.paid_at)
                 from pays y join public.profiles pf on pf.id = y.from_user join public.profiles pt on pt.id = y.to_user), '[]'::jsonb)));
end $$;

-- ---------- 4. Finalise one close (internal) ----------
create or replace function public.kh_finalize_period_close(p_close_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare c public.period_closes%rowtype; v_sum jsonb; v_exp uuid[]; v_pay uuid[]; m record;
begin
  select * into c from public.period_closes where id = p_close_id for update;
  if not found or c.status <> 'pending' then return; end if;
  if exists (select 1 from public.period_close_objections o where o.close_id = c.id) then return; end if;
  perform set_config('khatafy.purge', 'on', true);

  v_sum := public.kh_close_summary(c.group_id, c.cut_at);
  v_exp := array(select e.id from public.expenses e where e.group_id = c.group_id and e.spent_at < c.cut_at);
  v_pay := array(select p.id from public.payments p where p.group_id = c.group_id and p.paid_at < c.cut_at and p.status <> 'pending');

  -- remaining dues stay as a carried balance (net effect of the records about to be deleted)
  with old_exp as (select e.id, e.version, e.paid_by, e.amount_paise from public.expenses e
                   where e.group_id = c.group_id and e.status = 'active' and e.spent_at < c.cut_at),
  d as (select x.paid_by as uid, x.amount_paise as amt from old_exp x
        union all select es.user_id, -es.share_paise from public.expense_splits es join old_exp x on x.id = es.expense_id and x.version = es.version where es.group_id = c.group_id
        union all select pm.from_user, pm.amount_paise from public.payments pm where pm.id = any (v_pay) and pm.status = 'confirmed'
        union all select pm.to_user, -pm.amount_paise from public.payments pm where pm.id = any (v_pay) and pm.status = 'confirmed'),
  s as (select uid, sum(amt)::bigint as net from d group by uid having sum(amt) <> 0)
  insert into public.group_balance_carry (group_id, user_id, carry_paise)
  select c.group_id, s.uid, s.net from s
  on conflict (group_id, user_id) do update set carry_paise = public.group_balance_carry.carry_paise + excluded.carry_paise, updated_at = now();

  insert into public.storage_cleanup_queue (storage_path)
    select r.storage_path from public.expense_receipts r where r.group_id = c.group_id and r.expense_id = any (v_exp);
  delete from public.expense_receipts r where r.group_id = c.group_id and r.expense_id = any (v_exp);
  delete from public.expense_revisions r where r.group_id = c.group_id and r.expense_id = any (v_exp);
  delete from public.expense_splits s2 where s2.group_id = c.group_id and s2.expense_id = any (v_exp);
  delete from public.expenses e where e.group_id = c.group_id and e.id = any (v_exp);
  delete from public.payments p where p.id = any (v_pay);
  -- details that would leak what was bought / paid
  delete from public.audit_logs a where a.group_id = c.group_id and a.entity_type in ('expenses', 'payments')
    and a.entity_id = any (array(select x::text from unnest(v_exp || v_pay) x));
  delete from public.notifications n where n.group_id = c.group_id and n.created_at < c.cut_at
    and (n.type like 'expense\_%' or n.type like 'payment\_%');

  update public.period_closes set status = 'closed', closed_at = now(), summary = v_sum where id = c.id;
  perform public.kh_audit(c.group_id, 'period_closed', 'group', c.group_id::text,
    jsonb_build_object('period_end', c.period_end, 'expenses', coalesce(array_length(v_exp, 1), 0)));
  for m in select gm.user_id from public.group_members gm where gm.group_id = c.group_id and gm.status = 'active' loop
    perform public.kh_notify(m.user_id, c.group_id, 'close_done', jsonb_build_object('period_end', c.period_end));
  end loop;
end $$;

create or replace function public.kh_finalize_due_closes()
returns integer language plpgsql security definer set search_path = '' as $$
declare r record; n integer := 0;
begin
  for r in select id from public.period_closes where status = 'pending' and effective_at <= now() loop
    begin perform public.kh_finalize_period_close(r.id); n := n + 1;
    exception when others then raise warning 'period close % failed: %', r.id, sqlerrm; end;
  end loop;
  return n;
end $$;

-- ---------- 5. Client RPCs ----------
create or replace function public.request_period_close(p_group_id uuid, p_period_end date)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_require_role(p_group_id, 'admin'); g public.groups%rowtype; v_cut timestamptz; v_id uuid; v_name text; m record;
begin
  perform public.kh_require_active_group(p_group_id);
  perform public.kh_rate_limit('period_close', 10, 3600);
  select * into g from public.groups where id = p_group_id;
  if p_period_end is null or p_period_end > (now() at time zone g.timezone)::date then raise exception 'INVALID_CLOSE_DATE'; end if;
  v_cut := ((p_period_end + 1)::timestamp at time zone g.timezone);
  if exists (select 1 from public.period_closes c where c.group_id = p_group_id and c.status = 'closed' and c.cut_at >= v_cut) then raise exception 'INVALID_CLOSE_DATE'; end if;
  if exists (select 1 from public.period_closes c where c.group_id = p_group_id and c.status = 'pending') then raise exception 'CLOSE_ALREADY_PENDING'; end if;
  if not exists (select 1 from public.expenses e where e.group_id = p_group_id and e.status = 'active' and e.spent_at < v_cut) then raise exception 'NOTHING_TO_CLOSE'; end if;
  insert into public.period_closes (group_id, period_end, cut_at, requested_by, effective_at)
    values (p_group_id, p_period_end, v_cut, v_uid, now() + interval '7 days') returning id into v_id;
  perform public.kh_audit(p_group_id, 'period_close_requested', 'group', p_group_id::text, jsonb_build_object('period_end', p_period_end));
  select full_name into v_name from public.profiles where id = v_uid;
  for m in select gm.user_id from public.group_members gm where gm.group_id = p_group_id and gm.status = 'active' and gm.user_id <> v_uid loop
    perform public.kh_notify(m.user_id, p_group_id, 'close_requested', jsonb_build_object('name', v_name, 'period_end', p_period_end));
  end loop;
  return v_id;
end $$;

create or replace function public.object_period_close(p_close_id uuid, p_reason text)
returns void language plpgsql security definer set search_path = '' as $$
declare c public.period_closes%rowtype; v_uid uuid; v_name text;
begin
  select * into c from public.period_closes where id = p_close_id;
  if not found then raise exception 'CLOSE_NOT_FOUND'; end if;
  v_uid := public.kh_require_role(c.group_id, 'member');
  if c.status <> 'pending' then raise exception 'CLOSE_NOT_PENDING'; end if;
  if p_reason is null or char_length(trim(p_reason)) < 3 then raise exception 'REASON_REQUIRED'; end if;
  insert into public.period_close_objections (close_id, user_id, reason) values (c.id, v_uid, left(trim(p_reason), 300))
    on conflict (close_id, user_id) do update set reason = excluded.reason, created_at = now();
  select full_name into v_name from public.profiles where id = v_uid;
  perform public.kh_notify_admins(c.group_id, 'close_objection', jsonb_build_object('name', v_name), v_uid, null);
end $$;

create or replace function public.withdraw_period_objection(p_close_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_uid();
begin
  delete from public.period_close_objections o where o.close_id = p_close_id and o.user_id = v_uid;
end $$;

create or replace function public.cancel_period_close(p_close_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare c public.period_closes%rowtype; v_uid uuid; v_name text; m record;
begin
  select * into c from public.period_closes where id = p_close_id for update;
  if not found then raise exception 'CLOSE_NOT_FOUND'; end if;
  v_uid := public.kh_require_role(c.group_id, 'admin');
  if c.status <> 'pending' then raise exception 'CLOSE_NOT_PENDING'; end if;
  update public.period_closes set status = 'cancelled' where id = c.id;
  perform public.kh_audit(c.group_id, 'period_close_cancelled', 'group', c.group_id::text, '{}'::jsonb);
  select full_name into v_name from public.profiles where id = v_uid;
  for m in select gm.user_id from public.group_members gm where gm.group_id = c.group_id and gm.status = 'active' and gm.user_id <> v_uid loop
    perform public.kh_notify(m.user_id, c.group_id, 'close_cancelled', jsonb_build_object('name', v_name));
  end loop;
end $$;

-- Closed periods (stored summary) + the pending one (live preview). Objection reasons only for admins.
create or replace function public.list_period_closes(p_group_id uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_uid uuid := public.kh_require_role(p_group_id, 'member'); v_admin boolean;
begin
  v_admin := exists (select 1 from public.group_members gm where gm.group_id = p_group_id and gm.user_id = v_uid and gm.status = 'active' and gm.role in ('owner', 'admin'));
  return coalesce((select jsonb_agg(x order by x.cut_at desc) from (
    select c.id, c.status, c.period_end, c.cut_at, c.requested_at, c.effective_at, c.closed_at, rp.full_name as requested_by_name,
      case when c.status = 'pending' then public.kh_close_summary(c.group_id, c.cut_at) else c.summary end as summary,
      (select count(*) from public.period_close_objections o where o.close_id = c.id) as objection_count,
      exists (select 1 from public.period_close_objections o where o.close_id = c.id and o.user_id = v_uid) as my_objection,
      case when v_admin then coalesce((select jsonb_agg(jsonb_build_object('name', op.full_name, 'reason', o.reason))
        from public.period_close_objections o join public.profiles op on op.id = o.user_id where o.close_id = c.id), '[]'::jsonb) else '[]'::jsonb end as objections
    from public.period_closes c join public.profiles rp on rp.id = c.requested_by
    where c.group_id = p_group_id and c.status in ('pending', 'closed')) x), '[]'::jsonb);
end $$;

revoke all on function public.kh_close_summary(uuid, timestamptz) from public, anon, authenticated;
revoke all on function public.kh_finalize_period_close(uuid) from public, anon, authenticated;
revoke all on function public.kh_finalize_due_closes() from public, anon, authenticated;
revoke all on function public.request_period_close(uuid, date) from public, anon;
revoke all on function public.object_period_close(uuid, text) from public, anon;
revoke all on function public.withdraw_period_objection(uuid) from public, anon;
revoke all on function public.cancel_period_close(uuid) from public, anon;
revoke all on function public.list_period_closes(uuid) from public, anon;
grant execute on function public.request_period_close(uuid, date) to authenticated;
grant execute on function public.object_period_close(uuid, text) to authenticated;
grant execute on function public.withdraw_period_objection(uuid) to authenticated;
grant execute on function public.cancel_period_close(uuid) to authenticated;
grant execute on function public.list_period_closes(uuid) to authenticated;

-- Daily job, 03:00 India time (needs pg_cron: Dashboard -> Integrations -> Cron).
do $$ begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    begin perform cron.unschedule('khatafy-close-finalize'); exception when others then null; end;
    perform cron.schedule('khatafy-close-finalize', '30 21 * * *', 'select public.kh_finalize_due_closes()');
  else raise notice 'pg_cron is not enabled: closes will not finalise until you enable it and re-run this block.'; end if;
end $$;

commit;


-- ============================================================
-- 0015_close_review_3_days.sql
-- ============================================================
-- 0015: review window for "Close period" is now 3 days (was 7).
begin;

create or replace function public.request_period_close(p_group_id uuid, p_period_end date)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_uid uuid := public.kh_require_role(p_group_id, 'admin'); g public.groups%rowtype; v_cut timestamptz; v_id uuid; v_name text; m record;
begin
  perform public.kh_require_active_group(p_group_id);
  perform public.kh_rate_limit('period_close', 10, 3600);
  select * into g from public.groups where id = p_group_id;
  if p_period_end is null or p_period_end > (now() at time zone g.timezone)::date then raise exception 'INVALID_CLOSE_DATE'; end if;
  v_cut := ((p_period_end + 1)::timestamp at time zone g.timezone);
  if exists (select 1 from public.period_closes c where c.group_id = p_group_id and c.status = 'closed' and c.cut_at >= v_cut) then raise exception 'INVALID_CLOSE_DATE'; end if;
  if exists (select 1 from public.period_closes c where c.group_id = p_group_id and c.status = 'pending') then raise exception 'CLOSE_ALREADY_PENDING'; end if;
  if not exists (select 1 from public.expenses e where e.group_id = p_group_id and e.status = 'active' and e.spent_at < v_cut) then raise exception 'NOTHING_TO_CLOSE'; end if;
  insert into public.period_closes (group_id, period_end, cut_at, requested_by, effective_at)
    values (p_group_id, p_period_end, v_cut, v_uid, now() + interval '3 days') returning id into v_id;
  perform public.kh_audit(p_group_id, 'period_close_requested', 'group', p_group_id::text, jsonb_build_object('period_end', p_period_end));
  select full_name into v_name from public.profiles where id = v_uid;
  for m in select gm.user_id from public.group_members gm where gm.group_id = p_group_id and gm.status = 'active' and gm.user_id <> v_uid loop
    perform public.kh_notify(m.user_id, p_group_id, 'close_requested', jsonb_build_object('name', v_name, 'period_end', p_period_end));
  end loop;
  return v_id;
end $$;

-- pending closes that were already requested follow the new, shorter window
update public.period_closes set effective_at = least(effective_at, requested_at + interval '3 days') where status = 'pending';

revoke all on function public.request_period_close(uuid, date) from public, anon;
grant execute on function public.request_period_close(uuid, date) to authenticated;

commit;
